-- ══════════════════════════════════════════════════════════════════════════════
-- 0270_academy_expert_live_covers.sql
-- Lots #1 + #2 + #3 :
--  1) Couvertures SVG éditoriales sur les Niveaux 2, 3 et 4
--  2) Rattachement de `exercice_id` (exercices live BRVM) sur les Niveaux 1 à 4
--  3) Enrichissement du Niveau 4 : simulateurs 5/5 + 52 questions de quiz
--  4) Synchronisation idempotente de academy_exam_questions (debutant M1 + expert)
-- Généré par frontend/scripts/academy-lot-1-2-3.mjs le 2026-11-25
-- ══════════════════════════════════════════════════════════════════════════════

BEGIN;

DO $$
DECLARE
  v_content jsonb;
BEGIN
  -- 1. Couvertures des parcours Niveaux 2, 3 et 4
  UPDATE public.academy_courses
  SET content = jsonb_set(content, '{coverUrl}', '"/academy/cover-niveau-2-fondamental.svg"'::jsonb, true), updated_at = now()
  WHERE slug = 'academy-niveau-2-fondamental';

  UPDATE public.academy_courses
  SET content = jsonb_set(content, '{coverUrl}', '"/academy/cover-niveau-3-technique.svg"'::jsonb, true), updated_at = now()
  WHERE slug = 'academy-niveau-3-technique';

  UPDATE public.academy_courses
  SET content = jsonb_set(content, '{coverUrl}', '"/academy/cover-niveau-4-expert.svg"'::jsonb, true), updated_at = now()
  WHERE slug = 'academy-niveau-4-expert';

  -- 2. Mise à jour complète des 5 leçons du Niveau 4 (simulateurs + quiz 52Q + exercice_id L4)
  SELECT content INTO v_content FROM public.academy_courses WHERE slug = 'academy-niveau-4-expert' FOR UPDATE;
  IF v_content IS NULL THEN RAISE EXCEPTION 'Cours academy-niveau-4-expert introuvable'; END IF;
  IF NOT ((v_content->'lessons'->0->>'titre') LIKE 'Leçon 1 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : N4 position 0 inattendue (%)', v_content->'lessons'->0->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,0}', (v_content->'lessons'->0) || $n4_l1${"titre":"Leçon 1 — L’architecture du marché financier régional","module":"Module 1 — Régulation et intégrité du marché","categorie":"regulatory","duree_min":11,"sous_titre":"Qui réglemente, qui organise, qui conserve, qui négocie : les institutions du marché de l’UMOA et leurs rôles.","resume":"Le marché financier régional de l’UMOA repose sur quelques institutions aux rôles distincts. L’AMF-UMOA, qui a succédé au CREPMF, réglemente et contrôle ; la BRVM organise la cotation ; le Dépositaire central conserve les titres et règle les transactions ; les SGI sont les seules à pouvoir négocier en bourse. Cette leçon décrit chacun de ces rôles et ce qu’ils changent pour l’investisseur.","sections":[{"type":"definition","titre":"Les institutions et leurs rôles","contenu":"Le marché financier régional de l’UMOA réunit huit pays : Bénin, Burkina Faso, Côte d’Ivoire, Guinée-Bissau, Mali, Niger, Sénégal et Togo. Il repose sur quelques institutions communes, aux rôles distincts et complémentaires.\nL’AMF-UMOA est l’autorité de régulation : elle agrée les acteurs, vise les opérations proposées au public, contrôle et sanctionne. La BRVM est l’entreprise de marché : elle admet les titres à la cote, organise les séances et diffuse les cours. Le Dépositaire central / Banque de règlement conserve les titres et assure le dénouement des transactions. Les SGI sont les intermédiaires agréés, seuls habilités à négocier en bourse pour leurs clients.\nSavoir qui fait quoi a une utilité pratique. Une question sur votre compte-titres se pose d’abord à votre SGI ; une question sur une cotation relève de la BRVM ; une réclamation contre un intermédiaire peut être portée devant l’AMF-UMOA.","tableau":{"colonnes":["Institution","Rôle","Ce que cela signifie pour vous"],"lignes":[["AMF-UMOA","Autorité de régulation : agrément des acteurs, visa des opérations, contrôle et sanctions","C’est elle qui protège l’épargne publique et qui reçoit les réclamations"],["BRVM","Entreprise de marché : admission à la cote, cotation, diffusion des cours","Elle publie les cours, le Bulletin officiel de la cote et les avis"],["Dépositaire central / Banque de règlement","Conservation centrale des titres, règlement et livraison des transactions","Il garantit que vos titres existent et changent bien de main"],["SGI","Sociétés de gestion et d’intermédiation agréées : seules habilitées à négocier en bourse","Tout ordre passe par une SGI ; elle tient souvent votre compte-titres"],["Sociétés de gestion d’OPCVM","Gestion des fonds collectifs","Elles gèrent les FCP et SICAV que vous pouvez souscrire"]],"note":"Les banques, elles, sont supervisées par la Commission bancaire de l’UMOA, aux côtés de la BCEAO."}},{"type":"importance","titre":"Du CREPMF à l’AMF-UMOA","contenu":"Le Conseil régional de l’épargne publique et des marchés financiers (CREPMF) a été transformé en Autorité des marchés financiers de l’UMOA (AMF-UMOA). Le changement fait suite au Traité révisé de l’UMOA du 12 juillet 2019 ; il a pris effet le 1er octobre 2022.\nLa réforme a notamment doté l’autorité d’une Commission des sanctions et d’un Médiateur.\nLa Commission des sanctions statue sur les manquements des acteurs du marché. Le Médiateur, lui, recherche un règlement amiable des différends entre épargnants et acteurs du marché. Pour l’épargnant, ce second organe est le plus concret : il offre une voie de recours qui ne passe pas d’emblée par un tribunal.","etapes":[{"titre":"12 juillet 2019","detail":"Signature du Traité révisé de l’UMOA."},{"titre":"1er octobre 2022","detail":"Prise d’effet : l’AMF-UMOA a succédé au CREPMF.","cle":true},{"titre":"Depuis","detail":"L’AMF-UMOA agrée, contrôle et sanctionne ; une Commission des sanctions statue sur les manquements."}],"etapes_style":"frise"},{"type":"importance","titre":"Le circuit d’un ordre de bourse","contenu":"Un achat d’actions traverse plusieurs institutions avant que les titres n’arrivent sur votre compte. Chaque étape a son responsable.\nVous transmettez votre ordre à votre SGI, selon les moyens qu’elle propose. La SGI vérifie que vous disposez des fonds, puis place l’ordre sur le système de cotation électronique de la BRVM. Pendant la séance, le système rapproche les ordres d’achat et de vente selon leur prix, puis leur ordre d’arrivée.\nUne fois l’ordre exécuté, la transaction n’est pas terminée. Le Dépositaire central / Banque de règlement procède au dénouement : l’argent passe de l’acheteur au vendeur, les titres du compte du vendeur à celui de l’acheteur, dans un délai fixé par les règles du marché. C’est seulement alors que les titres sont réellement à vous.\nLes titres sont dématérialisés : il n’existe pas de certificat papier. Votre propriété est prouvée par l’inscription en compte.","flux":[{"titre":"Vous","detail":"Transmettez un ordre à votre SGI","icone":"actionnaires"},{"titre":"SGI","detail":"Place l’ordre sur le système de cotation","icone":"entreprise"},{"titre":"BRVM","detail":"Rapproche acheteurs et vendeurs","icone":"graphique"},{"titre":"Dépositaire central","detail":"Règle l’argent et livre les titres","icone":"paiement"},{"titre":"Compte-titres","detail":"Les actions sont inscrites à votre nom","icone":"piece"}],"simulation":{"type":"frais_ordre","consigne":"Simulez les frais cumulés prélevés dans la chaîne SGI, BRVM et DC/BR lors d’un ordre au comptant.","cours":25000,"quantite":10,"taux_frais_pct":1.4,"minimum_fcfa":2500}},{"type":"piege","titre":"Les confusions fréquentes","contenu":"Certaines confusions sur le rôle des institutions coûtent cher, surtout en cas de litige ou de difficulté d’une société.\nLa plus répandue consiste à croire que la cotation est une garantie. La BRVM vérifie qu’une société remplit les conditions d’admission et qu’elle publie ses informations ; elle ne garantit ni sa solidité, ni son dividende, ni son cours. Une société cotée peut voir ses résultats baisser, comme toute entreprise.\nLa deuxième, plus grave, concerne les intermédiaires. Des offres de « placements boursiers » à rendement élevé circulent par messagerie ou sur les réseaux sociaux, proposées par des personnes ou des sociétés qui ne sont pas des SGI agréées. Elles ne passent pas par le circuit décrit plus haut et n’offrent aucune de ses protections. L’AMF-UMOA publie la liste des acteurs agréés : vérifier un nom prend quelques minutes.","points":[{"titre":"Croire que la BRVM garantit les sociétés","detail":"La BRVM organise la cotation ; elle ne garantit ni la solidité des sociétés ni le cours.","verifier":"Les comptes publiés par la société."},{"titre":"Passer par un intermédiaire non agréé","detail":"Seule une SGI agréée peut négocier en bourse. Un « placement » proposé hors de ce circuit n’offre pas les mêmes protections.","verifier":"La liste des acteurs agréés publiée par l’AMF-UMOA."},{"titre":"S’étonner de l’ancien nom","detail":"Les documents antérieurs à octobre 2022 parlent de l’ex-CREPMF : il s’agit de la même autorité, sous son ancien nom.","verifier":"La date du document."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Quatre acteurs, quatre rôles. Devant une offre de placement, une question suffit souvent : qui est l’intermédiaire, et figure-t-il sur la liste des acteurs agréés par l’AMF-UMOA ?\nLes banques cotées relèvent en outre d’une autre supervision, celle de la Commission bancaire de l’UMOA, aux côtés de la BCEAO. Une banque cotée est donc contrôlée à deux titres : comme banque, et comme société dont les titres sont proposés au public.","points":[{"titre":"L’AMF-UMOA réglemente, agrée, contrôle et sanctionne"},{"titre":"La BRVM organise la cotation et publie les cours"},{"titre":"Le Dépositaire central conserve les titres et règle les transactions"},{"titre":"Seule une SGI agréée peut négocier vos ordres"}]}],"quiz":[{"question":"Quelle institution a succédé à l’ex-CREPMF ?","options":["La BCEAO","L’AMF-UMOA","La BRVM","La Commission bancaire"],"correct":1,"explication":"L’AMF-UMOA a succédé au CREPMF le 1er octobre 2022, à l’entrée en vigueur du Traité révisé de l’UMOA."},{"question":"Qui est seul habilité à négocier vos ordres en bourse ?","options":["Votre banque, quelle qu’elle soit","Une SGI agréée","La BRVM directement","Le Dépositaire central"],"correct":1,"explication":"Les ordres de bourse passent obligatoirement par une SGI agréée."},{"question":"Quel est le rôle du Dépositaire central / Banque de règlement ?","options":["Fixer les cours","Conserver les titres et régler les transactions","Agréer les SGI","Publier les comptes des sociétés"],"correct":1,"explication":"Il assure la conservation centrale des titres, le règlement et la livraison."},{"question":"La BRVM garantit-elle la solidité des sociétés cotées ?","options":["Oui, elle garantit toutes les sociétés cotées","Non : elle organise la cotation","Oui, pour le compartiment Prestige","Seulement pour les banques cotées"],"correct":1,"explication":"La cotation n’est pas une garantie : l’investisseur reste exposé au risque de la société."},{"question":"Quel organe la réforme de 2022 a-t-elle créé au sein de l’AMF-UMOA ?","options":["Une banque centrale","Une Commission des sanctions","Une nouvelle bourse","Un fonds de garantie des dépôts"],"correct":1,"explication":"La réforme a doté l’AMF-UMOA d’une Commission des sanctions et d’un Médiateur."},{"question":"À quelle date l’AMF-UMOA a-t-elle officiellement succédé à l’ex-CREPMF ?","options":["Le 1er janvier 1998","Le 1er octobre 2022","Le 15 mars 2015","Le 1er juillet 2024"],"correct":1,"explication":"Le Traité révisé de l’UMOA entré en vigueur le 1er octobre 2022 a transformé l’ex-CREPMF en AMF-UMOA."},{"question":"Pourquoi les espèces et titres des clients sont-ils cantonnés au DC/BR séparément des fonds propres de la SGI ?","options":["Pour protéger les avoirs des clients en cas de défaut de la SGI","Pour augmenter le dividende versé chaque année aux actionnaires","Pour permettre à la BRVM de fixer des cours sans carnet d’ordres","Pour dispenser les particuliers de tout prélèvement fiscal IRVM"],"correct":0,"explication":"La ségrégation des comptes au DC/BR isole les titres et avoirs des clients du bilan propre de l’intermédiaire."},{"question":"Quelle mission relève directement de la Bourse Régionale des Valeurs Mobilières (BRVM) ?","options":["La politique monétaire des huit États de l’UEMOA","L’organisation des séances de cotation et du carnet","La gestion individuelle des portefeuilles des particuliers","Le prélèvement de l’impôt sur le revenu des sociétés"],"correct":1,"explication":"La BRVM organise la cotation centralisée, la diffusion des cours officiels et la surveillance technique des séances."},{"question":"Un épargnant souhaite déposer une réclamation après un litige avec sa SGI. Quel recours interne existe depuis la réforme de 2022 ?","options":["Le Médiateur institué auprès de l’AMF-UMOA","La chambre commerciale du Fonds monétaire international","L’assemblée générale annuelle des sociétés du compartiment","Le service client de la Bourse de Dakar uniquement"],"correct":0,"explication":"La réforme instituant l’AMF-UMOA a mis en place un Médiateur chargé de traiter les différends entre épargnants et intervenants agréés."},{"question":"Qui délivre l’agrément indispensable pour exercer en tant que SGI dans l’espace UEMOA ?","options":["L’AMF-UMOA, autorité de régulation du marché financier","La chambre de commerce du pays du demandeur","Le conseil d’administration de chaque société cotée","La première SGI historique implantée à Abidjan"],"correct":0,"explication":"Seule l’AMF-UMOA délivre l’agrément aux SGI, sociétés de gestion d’OPCVM et autres acteurs du marché financier régional."},{"question":"Que se passe-t-il durant l’étape de règlement-livraison pilotée par le DC/BR après exécution d’un achat ?","options":["La SGI conserve les titres en papier dans ses propres coffres","Les titres sont virés au compte de l’acheteur contre espèces","La société émettrice verse immédiatement un dividende spécial","Le prix exécuté est recalculé selon la séance du lendemain"],"correct":1,"explication":"Le DC/BR garantit la livraison simultanée des titres sur le compte-titres de l’acheteur contre le règlement en espèces."}],"liens":[{"label":"Choisir sa SGI","href":"/comparateur-sgi"},{"label":"Les sociétés cotées","href":"/societes"},{"label":"La qualité de nos données","href":"/qualite-donnees"}],"avertissement":"Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.","charts":[],"qcm":{"question":"Quelle institution a succédé à l’ex-CREPMF ?","options":["La BCEAO","L’AMF-UMOA","La BRVM","La Commission bancaire"],"correct":1,"explication":"L’AMF-UMOA a succédé au CREPMF le 1er octobre 2022, à l’entrée en vigueur du Traité révisé de l’UMOA."},"nouveaute":{"type":"mis_a_jour","depuis":"2026-11-25"}}$n4_l1$::jsonb, true);
  IF NOT ((v_content->'lessons'->1->>'titre') LIKE 'Leçon 2 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : N4 position 1 inattendue (%)', v_content->'lessons'->1->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,1}', (v_content->'lessons'->1) || $n4_l2${"titre":"Leçon 2 — L’information et l’intégrité du marché","module":"Module 1 — Régulation et intégrité du marché","categorie":"regulatory","duree_min":11,"sous_titre":"Ce que les sociétés doivent publier, ce qu’est une information privilégiée, et les abus que la réglementation sanctionne.","resume":"Un marché ne fonctionne que si tous les investisseurs disposent de la même information au même moment. Les sociétés cotées ont donc des obligations de publication, périodiques et permanentes, et l’usage d’une information privilégiée est interdit. Cette leçon décrit ces obligations, les principaux abus de marché et les réflexes à adopter.","sections":[{"type":"definition","titre":"Deux obligations d’information","contenu":"Un marché ne fonctionne que si tous les investisseurs disposent de la même information au même moment. Si certains savent avant les autres, ceux qui ne savent pas achètent et vendent à des prix faussés, et finissent par se retirer. Les sociétés cotées ont donc deux obligations d’information.\nL’information périodique suit un calendrier : états financiers annuels certifiés, rapports d’activité en cours d’année, publiés dans des délais fixés par la réglementation. Elle permet de suivre la société dans la durée.\nL’information permanente répond à l’événement. Tout fait nouveau susceptible d’influencer sensiblement le cours doit être rendu public sans délai : un résultat très différent de l’attendu, un contrat majeur, un litige important, un changement de dirigeant. Le principe est que la publication suit le fait, et non le calendrier qui arrangerait la société.","points":[{"titre":"L’information périodique","detail":"États financiers annuels certifiés, rapports d’activité trimestriels et semestriels, publiés dans des délais fixés."},{"titre":"L’information permanente","detail":"Tout fait nouveau susceptible d’influencer sensiblement le cours doit être rendu public sans délai : résultat inattendu, contrat majeur, litige, changement de dirigeant."}]},{"type":"importance","titre":"L’information privilégiée","contenu":"Une information est dite privilégiée quand elle réunit trois caractères. Celui qui la détient ne doit ni s’en servir pour opérer, ni la communiquer, tant qu’elle n’est pas publique.\nExemple fictif : le directeur financier d’une société apprend, une semaine avant la publication, que le résultat annuel sera deux fois plus élevé que prévu. L’information est précise, elle n’est pas publique, et elle ferait évidemment monter le cours : elle est privilégiée. Tant qu’elle n’est pas publiée, il ne doit ni acheter d’actions, ni en parler à ses proches.\nL’interdiction ne vise pas seulement les dirigeants. Elle concerne aussi un salarié, un conseiller, et le proche à qui l’information a été confiée.","points":[{"titre":"Précise","detail":"Elle porte sur un fait ou un événement déterminé, pas sur une rumeur vague."},{"titre":"Non publique","detail":"Elle n’a pas encore été diffusée au marché par les canaux officiels."},{"titre":"Susceptible d’influencer le cours","detail":"Un investisseur raisonnable en tiendrait compte pour décider."}]},{"type":"cas","titre":"Les principaux abus de marché","contenu":"Les comportements visés par la réglementation, résumés à titre pédagogique. Ils ont un point commun : ils faussent le prix que paient les autres investisseurs.\nLe délit d’initié et la communication illicite exploitent une information privilégiée. La manipulation de cours et la fausse information n’ont pas besoin d’information secrète : elles créent une fausse image du marché, par des ordres ou par des messages.\nLa manipulation est un risque réel sur un marché peu liquide. Quand une valeur s’échange peu, quelques ordres placés au bon moment suffisent à déplacer sa clôture, donc la valorisation affichée de tous ses détenteurs. Un cours qui bondit en fin de séance sur très peu de titres mérite d’être regardé avec prudence, sans conclure pour autant à un abus.","tableau":{"colonnes":["Abus","En quoi il consiste","Exemple pédagogique"],"lignes":[["Délit d’initié","Opérer ou faire opérer grâce à une information privilégiée","Un salarié achète avant l’annonce d’un résultat exceptionnel"],["Communication illicite","Transmettre une information privilégiée hors du cadre de ses fonctions","Un conseiller confie l’annonce à venir à un proche"],["Manipulation de cours","Passer des ordres pour fixer artificiellement un cours","Des achats répétés en fin de séance pour gonfler la clôture"],["Fausse information","Diffuser une information trompeuse pour influencer le cours","Une rumeur inventée de rachat publiée sur les réseaux"]],"note":"L’AMF-UMOA enquête et sanctionne ; des poursuites pénales relèvent des législations nationales."},"simulation":{"type":"carnet","niveaux":[{"prix":4000,"quantite":20},{"prix":4250,"quantite":15},{"prix":4600,"quantite":25}],"quantite_defaut":45,"codes":["SNTS","SGBC","ORAC"]}},{"type":"importance","titre":"Pourquoi cela concerne aussi le petit investisseur","contenu":"Les abus de marché ne sont pas réservés aux initiés. Relayer une rumeur de rachat dans un groupe de discussion, ou acheter sur la foi d’un « tuyau » venu de l’intérieur d’une société, expose à des risques réels.\nSur un marché peu liquide, quelques ordres suffisent à déplacer un cours : la vigilance y est d’autant plus nécessaire.\nLe cas le plus courant passe par les messageries. Un message annonce un rachat imminent, une hausse « assurée », un résultat connu d’avance. Soit l’information est fausse, et ceux qui l’ont lancée vendent pendant que les autres achètent ; soit elle est vraie et non publique, et l’utiliser est interdit. Dans les deux cas, acheter sur cette base est une erreur.\nTransférer un tel message n’est pas anodin non plus : diffuser une information trompeuse pour influencer un cours fait partie des abus de marché."},{"type":"piege","titre":"Les bons réflexes","contenu":"Quelques règles simples protègent à la fois votre épargne et votre responsabilité.\nLa source d’abord. Les avis de la BRVM, les communiqués des sociétés et les documents visés par l’AMF-UMOA font foi. Une information qui ne figure dans aucun de ces canaux n’est pas encore une information de marché, quelle que soit la personne qui la relaie.\nLa date ensuite. Une vraie information, mais ancienne, peut circuler de nouveau comme si elle était fraîche. Vérifier la date d’un communiqué évite d’acheter sur une nouvelle que le cours a intégrée depuis longtemps.\nEnfin, l’AMF-UMOA reçoit les signalements et les réclamations des épargnants. Un comportement suspect, une offre douteuse ou un intermédiaire non agréé peuvent lui être signalés par les canaux indiqués sur son site.","points":[{"titre":"Se fier aux publications officielles","detail":"Les avis de la BRVM et les communiqués des sociétés font foi, pas les rumeurs.","verifier":"La source et la date de l’information."},{"titre":"Se méfier des « tuyaux »","detail":"Une information présentée comme confidentielle et sûre est soit fausse, soit interdite d’usage.","verifier":"Si elle est publique."},{"titre":"Signaler un abus","detail":"Un comportement suspect peut être signalé à l’AMF-UMOA.","verifier":"Les canaux de réclamation de l’AMF-UMOA."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Même information, au même moment, pour tous. C’est la condition de la confiance, donc de la liquidité du marché.\nPour l’épargnant, la règle pratique est simple : ne décider que sur des informations publiques et officielles, datées et sourcées. Ce qui circule en privé est soit faux, soit interdit d’usage ; dans les deux cas, ce n’est pas une base de décision.","points":[{"titre":"Information périodique et permanente : deux obligations des sociétés cotées"},{"titre":"Information privilégiée : précise, non publique, et pouvant influencer le cours"},{"titre":"Délit d’initié, manipulation, fausse information : des abus sanctionnés"},{"titre":"Ne décider que sur des informations publiques et officielles"}]}],"quiz":[{"question":"Quels sont les trois caractères d’une information privilégiée ?","options":["Ancienne, publique, sans effet","Précise, non publique, susceptible d’influencer le cours","Vague, publique, chiffrée","Officielle, ancienne, confidentielle"],"correct":1,"explication":"Une information privilégiée est précise, non encore publique, et susceptible d’influencer sensiblement le cours."},{"question":"Une société signe un contrat majeur. Que lui impose l’information permanente ?","options":["D’attendre la publication du rapport annuel","De le rendre public sans délai","De n’en parler qu’aux grands actionnaires","Rien tant que le contrat n’est pas exécuté"],"correct":1,"explication":"Tout fait susceptible d’influencer sensiblement le cours doit être publié sans délai."},{"question":"Des achats répétés en fin de séance pour gonfler le cours de clôture relèvent :","options":["D’une stratégie normale","De la manipulation de cours","D’une information périodique","D’un dividende"],"correct":1,"explication":"Fixer artificiellement un cours par ses ordres est une manipulation."},{"question":"Un ami salarié d’une société cotée vous annonce un excellent résultat, pas encore publié. Que faire ?","options":["Acheter avant que l’annonce ne soit publiée","Ne pas opérer : l’information est privilégiée","La relayer à d’autres pour qu’ils en profitent","Vendre à découvert pour couvrir le risque"],"correct":1,"explication":"Utiliser ou transmettre une information privilégiée est interdit, pour lui comme pour vous."},{"question":"Qui enquête et sanctionne les abus de marché dans l’UMOA ?","options":["La BRVM seule","L’AMF-UMOA","Chaque SGI","Personne"],"correct":1,"explication":"L’AMF-UMOA enquête et sanctionne ; des poursuites pénales relèvent des législations nationales."},{"question":"Qu’est-ce qu’une « fenêtre négative » (black-out period) appliquée aux dirigeants d’une société cotée ?","options":["Une interdiction temporaire d’intervenir sur les titres avant publication","Une suspension automatique de l’action pendant trois mois consécutifs","Une exonération fiscale accordée aux fondateurs lors des dividendes","Une séance réservée aux ordres exécutés par la SGI chef de file"],"correct":0,"explication":"Avant la publication des comptes, les dirigeants doivent s’abstenir d’acheter ou de vendre afin d’éviter tout soupçon de délit d’initié."},{"question":"Deux complices se vendent et s’achètent simultanément le même titre au même prix pour gonfler le volume affiché. De quel abus s’agit-il ?","options":["D’une offre publique d’achat obligatoire","D’une manipulation de marché par opérations fictives","D’un fractionnement régulier de la valeur nominale","D’une couverture réglementaire imposée par le DC/BR"],"correct":1,"explication":"Créer une apparence artificielle d’activité ou de liquidité trompe les autres investisseurs : c’est une manipulation de cours prohibée."},{"question":"Transmettre à un proche un tuyau confidentiel avant la publication officielle d’une acquisition constitue :","options":["Une pratique courante tolérée hors séance boursière","Une communication illicite d’information privilégiée","Un service commercial normal entre actionnaires individuels","Une obligation liée à la transparence financière permanente"],"correct":1,"explication":"Communiquer une information privilégiée hors du cadre professionnel normal expose l’initié et le bénéficiaire à des sanctions."},{"question":"Quel type de message relayé sur les réseaux sociaux peut être sanctionné au titre de la manipulation de marché ?","options":["La diffusion d’informations fausses ou trompeuses sur une société","La lecture publique du dernier bilan annuel officiel certifié","Le calcul d’un multiple PER à partir du Bulletin officiel de la cote","L’analyse comparative de deux exercices historiques déjà publiés"],"correct":0,"explication":"Propager sciemment des rumeurs fausses ou trompeuses susceptibles d’orienter artificiellement le cours relève de l’abus de marché."},{"question":"Quelle distinction sépare le travail d’enquête de la décision de sanction à l’AMF-UMOA ?","options":["La Commission des sanctions statue indépendamment des enquêteurs","Les deux rôles reviennent uniquement au directeur général de la BRVM","Seules les SGI votent les amendes lors des assemblées générales","La BCEAO tranche les dossiers en remplaçant les juges civils"],"correct":0,"explication":"Pour garantir un procès équitable, les poursuites et l’instruction sont séparées de l’organe indépendant qui prononce les sanctions."}],"liens":[{"label":"Les sociétés cotées","href":"/societes"},{"label":"Les opérations sur titres","href":"/operations-titres"},{"label":"La qualité de nos données","href":"/qualite-donnees"}],"avertissement":"Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.","charts":[],"qcm":{"question":"Quels sont les trois caractères d’une information privilégiée ?","options":["Ancienne, publique, sans effet","Précise, non publique, susceptible d’influencer le cours","Vague, publique, chiffrée","Officielle, ancienne, confidentielle"],"correct":1,"explication":"Une information privilégiée est précise, non encore publique, et susceptible d’influencer sensiblement le cours."},"nouveaute":{"type":"mis_a_jour","depuis":"2026-11-25"}}$n4_l2$::jsonb, true);
  IF NOT ((v_content->'lessons'->2->>'titre') LIKE 'Leçon 3 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : N4 position 2 inattendue (%)', v_content->'lessons'->2->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,2}', (v_content->'lessons'->2) || $n4_l3${"titre":"Leçon 3 — Les compartiments et les indices de la BRVM","module":"Module 2 — Marché primaire et introduction en bourse","categorie":"general","duree_min":9,"sous_titre":"Prestige, Principal, Croissance : comment la BRVM classe ses valeurs depuis 2023, et ce que mesurent ses indices.","resume":"Depuis le 2 janvier 2023, le marché des actions de la BRVM est organisé en trois compartiments : Prestige, Principal et Croissance. Les critères tiennent à l’ancienneté, à la taille, au flottant et à la qualité de l’information. De nouveaux indices sont nés en même temps. Cette leçon explique ces classements et ce qu’on peut en lire.","sections":[{"type":"definition","titre":"Trois compartiments","contenu":"La réorganisation est entrée en vigueur le 2 janvier 2023, selon le communiqué publié par la BRVM ce jour-là. Le marché des actions est depuis organisé en trois compartiments : Prestige, Principal et Croissance.\nLe Prestige réunit les grandes sociétés établies, qui remplissent des critères exigeants de taille, d’ancienneté, de flottant et de qualité de l’information. Le Principal accueille les sociétés cotées qui remplissent les critères généraux d’admission sans atteindre ceux du Prestige. Le Croissance est destiné aux PME et aux entreprises à fort potentiel de croissance, avec des conditions d’accès allégées.\nLe flottant est la part du capital qui circule réellement en bourse, par opposition aux titres gardés par les actionnaires de référence. Un flottant important signifie davantage de titres disponibles à l’achat et à la vente, donc en principe une meilleure liquidité. C’est pourquoi il figure parmi les critères du Prestige.","tableau":{"colonnes":["Compartiment","Pour qui","Critères publiés"],"lignes":[["Prestige","Les grandes sociétés établies","10 ans d’activité, 50 Md FCFA de capitalisation, flottant d’au moins 20 % et nombre minimal de titres, information régulière, engagement RSE"],["Principal","Les sociétés cotées qui ne relèvent pas du Prestige","Les critères d’admission généraux de la BRVM"],["Croissance","Les PME et les entreprises à fort potentiel de croissance","Des conditions d’accès allégées, avec un accompagnement spécifique"]],"note":"Source : communiqué de la BRVM du 2 janvier 2023. Le règlement de la BRVM fait foi pour le détail des critères."}},{"type":"importance","titre":"Les indices de la BRVM","contenu":"Un indice résume en un seul chiffre l’évolution d’un groupe de valeurs. Depuis 2023, la BRVM publie notamment trois indices de référence, à côté d’indices par compartiment et par secteur.\nLe BRVM Composite regroupe toutes les sociétés cotées, pondérées par leur capitalisation : il mesure l’ensemble du marché, avec un poids prépondérant pour les plus grandes. Le BRVM 30 retient les trente valeurs les plus échangées sur un trimestre ; sa composition suit donc la liquidité des titres. Le BRVM Prestige suit les valeurs du compartiment Prestige.\nUn indice se lit comme une variation, pas comme un niveau. Son nombre de points n’a pas de sens en soi ; ce qui compte est son évolution sur une période, comparée à celle d’un autre indice ou d’un portefeuille.","points":[{"titre":"BRVM Composite","detail":"Toutes les sociétés cotées, pondérées par leur capitalisation."},{"titre":"BRVM 30","detail":"Les trente valeurs les plus échangées sur un trimestre ; il a remplacé le BRVM 10."},{"titre":"BRVM Prestige","detail":"Les valeurs du compartiment Prestige ; sa composition est révisée chaque année."}],"simulation":{"type":"technique","consigne":"Observez l’évolution récente de valeurs phares éligibles aux indices et compartiments de la BRVM.","indicateur":"variation","codes":["SNTS","ORAC","SGBC"]}},{"type":"cas","titre":"Sur la BRVM : les indices à la dernière séance","reel":true,"contenu":"Les valeurs des principaux indices, lues en base à l’ouverture de la leçon.\nComparez leurs variations plutôt que leurs niveaux. Si le BRVM Prestige progresse nettement plus que le BRVM Composite, le mouvement du marché est porté par les grandes valeurs ; s’il progresse moins, ce sont plutôt les autres qui tirent le marché. La même lecture vaut pour le BRVM Principal.\nCes comparaisons décrivent le marché d’une séance ; elles ne disent rien de ce que fera un indice à la séance suivante.","donnees_reelles":{"vue":"indices","codes":["BRVMC","BRVM30","BRVMPRES","BRVMPRIN"]}},{"type":"piege","titre":"Ce qu’un compartiment ne dit pas","contenu":"Un classement décrit des caractéristiques, pas une qualité d’investissement. Trois malentendus sont fréquents.\nLe premier consiste à lire « Prestige » comme une garantie. Les critères portent sur la taille, l’ancienneté, le flottant et l’information publiée. Ils ne disent rien du prix de l’action ni des résultats futurs : une grande société bien informée peut être chère, et son cours peut baisser.\nLe deuxième est symétrique : « Croissance » désigne le profil des entreprises accueillies, pas une croissance assurée. Ces sociétés sont souvent plus jeunes, plus petites et moins échangées, donc plus risquées.\nLe troisième concerne les indices pondérés par la capitalisation. Quand quelques valeurs représentent une grande part de la capitalisation totale, elles dictent l’évolution de l’indice. Un indice en hausse peut ainsi cacher une majorité de valeurs en baisse.","points":[{"titre":"Prestige ne veut pas dire « sans risque »","detail":"Une grande société peut voir ses résultats baisser et son cours reculer.","verifier":"Les comptes et la valorisation de la société."},{"titre":"Croissance ne veut pas dire « croissance assurée »","detail":"Le compartiment accueille des entreprises jeunes, souvent plus risquées et moins liquides.","verifier":"La liquidité et l’historique de la valeur."},{"titre":"Un indice pondéré par la capitalisation est concentré","detail":"Quelques grandes valeurs y pèsent lourd.","verifier":"Le poids des premières valeurs dans l’indice."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Classer n’est pas recommander. Un compartiment renseigne sur la taille, le flottant et la transparence d’une société ; il ne remplace ni la lecture de ses comptes, ni l’examen de son prix.\nLes indices servent de repères pour situer un portefeuille : comparer sa performance à celle du BRVM Composite, sur la même période, dit si vos choix ont fait mieux ou moins bien que le marché.","points":[{"titre":"Trois compartiments depuis le 2 janvier 2023 : Prestige, Principal, Croissance"},{"titre":"Prestige : 10 ans, 50 Md FCFA de capitalisation, 20 % de flottant"},{"titre":"BRVM Composite, BRVM 30, BRVM Prestige : trois indices de référence"},{"titre":"Un compartiment décrit une société, il ne juge pas son action"}]}],"quiz":[{"question":"Depuis quand le marché des actions de la BRVM est-il organisé en compartiments Prestige, Principal et Croissance ?","options":["1998","2 janvier 2023","1er octobre 2022","2026"],"correct":1,"explication":"La réorganisation est entrée en vigueur le 2 janvier 2023."},{"question":"Quel flottant minimum le compartiment Prestige exige-t-il ?","options":["5 % du capital","20 % du capital","50 % du capital","Aucun"],"correct":1,"explication":"Le communiqué de la BRVM fixe un flottant d’au moins 20 % du capital, assorti d’un nombre minimal de titres fixé par le règlement des compartiments."},{"question":"Que regroupe l’indice BRVM 30 ?","options":["Les 30 plus grandes capitalisations","Les 30 valeurs les plus échangées sur un trimestre","Les 30 plus anciennes sociétés","30 obligations"],"correct":1,"explication":"Le BRVM 30 regroupe les trente valeurs les plus échangées sur un trimestre."},{"question":"À qui s’adresse le compartiment Croissance ?","options":["Aux banques uniquement","Aux PME et aux entreprises à fort potentiel de croissance","Aux États","Aux OPCVM"],"correct":1,"explication":"Le compartiment Croissance est destiné aux PME et aux entreprises à fort potentiel de croissance."},{"question":"Une société du compartiment Prestige est-elle un placement sans risque ?","options":["Oui, puisqu’elle est parmi les plus grandes","Non : le compartiment ne dit rien du cours","Oui, si elle verse un dividende régulier","Oui, pendant ses dix premières années"],"correct":1,"explication":"Le classement repose sur des critères de taille, de flottant et d’information, pas sur une garantie de performance."},{"question":"Comment sont pondérées les actions au sein de l’indice BRVM Composite ?","options":["De manière strictement égale entre les sociétés cotées","Selon leur capitalisation boursière respective sur la cote","Uniquement selon le montant du dividende versé l’année précédente","À parts fixes selon le pays d’implantation du siège social"],"correct":1,"explication":"Un indice pondéré par la capitalisation donne un poids proportionnel à la taille boursière de chaque émetteur."},{"question":"Quelle différence distingue le BRVM 30 du BRVM Principal en termes de nature ?","options":["Le BRVM 30 est un indice, alors que le Principal est un compartiment","Le BRVM 30 réunit les obligations souveraines et le Principal les actions","Le BRVM Principal rassemble uniquement des PME non encore rentables","Le BRVM 30 mesure l’inflation moyenne de la zone UEMOA"],"correct":0,"explication":"Les compartiments (Prestige, Principal, Croissance) classent les sociétés admises ; le BRVM 30 est un indice mesurant les 30 valeurs les plus actives."},{"question":"Quel principe permet à une société initialement cotée sur le compartiment Principal ou Croissance de changer de catégorie ?","options":["Le respect durable des critères exigés lors de la revue annuelle","Une décision libre prise par le PDG sans examen de la BRVM","Une augmentation ponctuelle du cours sur une seule séance","Le versement d’un dividende exceptionnel supérieur à 20 %"],"correct":0,"explication":"La BRVM vérifie périodiquement les critères de flottant, capitalisation, liquidité et gouvernance avant tout reclassement."},{"question":"À quoi servent les indices sectoriels publiés parallèlement au BRVM Composite ?","options":["À suivre la performance d’un secteur précis face au marché global","À garantir un rendement minimal aux détenteurs d’actions bancaires","À remplacer les rapports annuels certifiés des entreprises cotées","À fixer le tarif des frais de courtage pratiqués par les SGI"],"correct":0,"explication":"Les indices sectoriels (Finance, Télécoms, Services publics, Distribution…) isolent la dynamique propre à chaque branche d’activité."},{"question":"Pourquoi un indice large peut-il monter alors que la majorité des titres de la cote stagne ?","options":["Parce que deux ou trois très grosses capitalisations tirent la moyenne","Parce que la BRVM retire automatiquement les valeurs en baisse","Parce que l’indice intègre les dépôts à terme des banques centrales","Parce que les dividendes sont comptés en double dans le calcul"],"correct":0,"explication":"Dans un indice pondéré par la capitalisation, les plus grandes valeurs représentent une part majeure de la variation totale."}],"liens":[{"label":"Les secteurs et les indices","href":"/secteurs"},{"label":"Les sociétés cotées","href":"/societes"},{"label":"La liquidité de chaque valeur","href":"/liquidite"}],"avertissement":"Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.","charts":[],"qcm":{"question":"Depuis quand le marché des actions de la BRVM est-il organisé en compartiments Prestige, Principal et Croissance ?","options":["1998","2 janvier 2023","1er octobre 2022","2026"],"correct":1,"explication":"La réorganisation est entrée en vigueur le 2 janvier 2023."},"nouveaute":{"type":"mis_a_jour","depuis":"2026-11-25"}}$n4_l3$::jsonb, true);
