    RAISE EXCEPTION 'Migration 0270 : N4 position 3 inattendue (%)', v_content->'lessons'->3->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,3}', (v_content->'lessons'->3) || $n4_l4${"titre":"Leçon 4 — Pourquoi une société entre en bourse","module":"Module 2 — Marché primaire et introduction en bourse","categorie":"fundamental","duree_min":10,"sous_titre":"Lever des fonds, donner une valeur à l’entreprise, permettre à des actionnaires de sortir : les raisons, les coûts et les contraintes.","resume":"Une introduction en bourse permet à une société de lever des capitaux ou à ses actionnaires de céder une partie de leurs titres au public. Elle apporte de la visibilité et une valeur de marché, mais impose transparence, coûts et contraintes durables. Cette leçon présente ces arbitrages, avec l’exemple de l’admission de Bridge Bank Group Côte d’Ivoire à la BRVM, en septembre 2026.","sections":[{"type":"definition","titre":"Deux façons d’entrer en bourse","contenu":"Une société peut entrer en bourse de deux façons, et la différence décide de qui reçoit l’argent des souscripteurs.\nDans une augmentation de capital, la société émet des actions nouvelles. L’argent versé par les souscripteurs entre dans ses caisses : elle peut financer des investissements, rembourser des dettes ou renforcer ses fonds propres. Les actionnaires existants voient leur part diluée, en échange de ces moyens nouveaux.\nDans une offre publique de vente, des actionnaires existants cèdent une partie de leurs titres au public. L’argent va aux vendeurs, pas à la société : un État qui privatise, un fondateur qui prépare sa succession, un fonds d’investissement qui sort. La société elle-même ne lève rien. Une opération mixte combine les deux.\nAucune formule n’est meilleure que l’autre, mais elles ne racontent pas la même histoire. La note d’information décrit la structure de l’opération.","tableau":{"colonnes":["Opération","Ce qui est vendu","À qui va l’argent"],"lignes":[["Augmentation de capital","Des actions nouvelles","À la société, qui peut investir"],["Offre publique de vente (OPV)","Des actions existantes","Aux actionnaires qui cèdent leurs titres"],["Opération mixte","Les deux à la fois","En partie à la société, en partie aux vendeurs"]],"note":"Lire la note d’information pour savoir qui reçoit l’argent levé : c’est une indication sur le projet."}},{"type":"importance","titre":"Ce que la société gagne, ce qu’elle accepte","contenu":"L’introduction est un arbitrage durable, pas un événement d’un jour. La société gagne des avantages réels et accepte en échange des obligations qui dureront tant qu’elle restera cotée.\nLe principal avantage est l’accès à l’épargne du public, aujourd’hui et plus tard : une société cotée peut lever à nouveau des fonds, par une augmentation de capital ou un emprunt obligataire, auprès d’investisseurs qui la connaissent déjà. La cotation donne aussi une valeur de marché quotidienne, utile pour une transmission ou un accord avec un partenaire, et une notoriété auprès des clients et des banques.\nEn contrepartie, la société publie régulièrement ses comptes et tout fait important, se soumet au contrôle de l’AMF-UMOA et rend des comptes à de nombreux actionnaires. Elle supporte aussi des coûts : conseils, SGI chef de file, frais d’admission et de cotation, communication financière. Rapportés à sa taille, ces coûts pèsent plus lourd pour une petite entreprise.","points":[{"titre":"Gains","detail":"Accès à l’épargne du public, valeur de marché quotidienne, notoriété, possibilité de lever à nouveau des fonds plus tard."},{"titre":"Contraintes","detail":"Publication régulière des comptes et des faits importants, contrôle de l’AMF-UMOA, assemblées ouvertes à de nombreux actionnaires."},{"titre":"Coûts","detail":"Rémunération des conseils et de la SGI chef de file, frais d’admission et de cotation, coûts de communication financière."}]},{"type":"cas","titre":"Un exemple récent : Bridge Bank Group Côte d’Ivoire","contenu":"Bridge Bank Group Côte d’Ivoire (code BBGC) est devenue la 48e société cotée de la BRVM, avec une première cotation le 24 septembre 2026. Les chiffres de l’offre sont ceux publiés à l’issue de l’opération.\nCette opération illustre plusieurs notions de la leçon. C’était une offre publique de vente : l’argent des souscripteurs est allé aux actionnaires qui ont cédé leurs titres, pas à la banque. Le taux de souscription de 142 % signifie que les demandes représentaient 1,42 fois les titres offerts : tous les ordres n’ont pas pu être servis en entier.\nCes chiffres décrivent l’opération à son issue. Ils ne disent rien de l’évolution du cours depuis la première cotation, que la section suivante lit en base.","stats":[{"label":"Type d’opération","valeur":"Offre publique de vente","detail":"Cession d’actions existantes au public"},{"label":"Titres offerts","valeur":"10 millions d’actions","detail":"Selon les résultats publiés de l’offre"},{"label":"Prix de l’offre","valeur":"6 750 FCFA","detail":"Par action"},{"label":"Taux de souscription","valeur":"142 %","detail":"La demande a dépassé l’offre : les ordres ont été servis en partie"},{"label":"Première cotation","valeur":"24 septembre 2026","detail":"48e société cotée de la BRVM"}],"simulation":{"type":"souscription_ipo","consigne":"Chiffres publiés de l’offre BBGC. Indiquez le nombre de titres que vous auriez demandés : la réduction suit ici une règle proportionnelle.","titres_offerts":10000000,"prix":6750,"taux_souscription_pct":142,"demande":100}},{"type":"cas","titre":"Sur la BRVM : le cours aujourd’hui","reel":true,"contenu":"Le dernier cours de BBGC, lu en base à l’ouverture de la leçon, à comparer au prix de l’offre de 6 750 FCFA. Un écart dans un sens ou dans l’autre ne dit rien de la qualité de la société : il dit ce que le marché paie aujourd’hui.\nPour interpréter cet écart, rapportez-le au temps écoulé et aux résultats publiés depuis l’introduction. Juste après la cotation, le cours reflète surtout l’équilibre entre ceux qui veulent compléter leur ligne et ceux qui veulent encaisser ; plusieurs mois plus tard, il reflète davantage les comptes publiés. Les volumes des séances récentes disent si ce cours repose sur des échanges nombreux ou sur quelques ordres.","donnees_reelles":{"vue":"cours","codes":["BBGC"],"actions":100}},{"type":"piege","titre":"Les illusions de l’introduction","contenu":"Une introduction attire l’attention de la presse et des réseaux sociaux. Elle mérite pourtant la même analyse que n’importe quel achat, sur les comptes et sur le prix.\nLa sursouscription est souvent présentée comme une preuve de qualité. Elle prouve seulement que l’offre a plu à de nombreux investisseurs au prix proposé. Elle a même un effet direct sur vous : plus la demande dépasse l’offre, plus votre ordre est réduit, et moins vous recevez de titres.\nLa structure de l’opération est souvent oubliée. Dans une offre publique de vente, demandez-vous pourquoi les vendeurs vendent, et à ce prix-là. Ce n’est pas forcément un mauvais signe, mais la question est légitime.\nLa liquidité après la cotation, enfin, déçoit souvent. Une fois l’opération passée, beaucoup de souscripteurs gardent leurs titres, et les échanges peuvent devenir rares. Revendre vite peut alors se faire à un prix moins favorable qu’espéré.","points":[{"titre":"« Sursouscrite, donc bonne affaire »","detail":"Une forte demande dit que l’offre plaît, pas que le prix est bas. Elle réduit aussi la part servie à chacun.","verifier":"La valorisation implicite du prix d’offre."},{"titre":"Oublier qui vend","detail":"Dans une offre publique de vente, l’argent va aux vendeurs, pas à la société.","verifier":"La structure de l’opération dans la note d’information."},{"titre":"Ignorer la liquidité après la cotation","detail":"Une valeur nouvelle peut s’échanger peu une fois l’enthousiasme passé.","verifier":"Les volumes des premières semaines."}]},{"type":"retenir","titre":"L’essentiel","contenu":"Une introduction se juge comme un achat : sur les comptes de la société et sur le prix demandé. Le contexte, la publicité et le taux de souscription ne remplacent pas cette analyse.\nAvant de souscrire, calculez avec les chiffres de la note d’information le PER et le P/B qu’implique le prix d’offre, comme au niveau 2, et comparez-les à ceux des sociétés cotées du même secteur. Si la société paraît plus chère que ses comparables, la note doit vous donner une raison de l’accepter.","points":[{"titre":"Augmentation de capital : l’argent va à la société ; OPV : aux vendeurs"},{"titre":"La cotation apporte fonds et visibilité, contre transparence et coûts"},{"titre":"Une offre sursouscrite n’est pas forcément bon marché"},{"titre":"Lire la note d’information avant de souscrire"}]}],"quiz":[{"question":"Dans une offre publique de vente, à qui va l’argent des souscripteurs ?","options":["À la société","Aux actionnaires qui cèdent leurs titres","À la BRVM","À l’AMF-UMOA"],"correct":1,"explication":"Une OPV porte sur des actions existantes : le produit va aux vendeurs."},{"question":"Une offre de 10 millions d’actions reçoit des demandes pour 14,2 millions. Quel est le taux de souscription ?","options":["70 %","100 %","142 %","242 %"],"correct":2,"explication":"14,2 ÷ 10 = 142 %."},{"question":"Dans le même cas, si toutes les demandes sont réduites de façon égale, quelle part de sa demande chacun reçoit-il ?","options":["Environ 50 %","Environ 70 %","100 %","142 %"],"correct":1,"explication":"10 ÷ 14,2 ≈ 70 % de la demande servie."},{"question":"Quelle contrainte durable accepte une société en entrant en bourse ?","options":["Ne plus jamais verser de dividende","Publier régulièrement ses comptes et les faits importants","Fermer son capital","Changer de pays"],"correct":1,"explication":"La cotation impose une information périodique et permanente, sous le contrôle de l’AMF-UMOA."},{"question":"Une introduction très sursouscrite garantit-elle une hausse du cours ?","options":["Oui, au moins pendant la première année","Non : la demande ne fixe pas le cours futur","Oui, si la société cotée est une banque solide","Oui, dès la première séance de cotation"],"correct":1,"explication":"Une forte demande ne garantit rien. Le cours dépend ensuite des résultats et du prix payé."},{"question":"Lors d’une introduction réalisée uniquement par augmentation de capital, à qui reviennent les fonds versés par les nouveaux actionnaires ?","options":["Aux anciens actionnaires fondateurs qui cèdent leurs parts","Directement à l’entreprise pour financer ses projets ou sa dette","Au budget annuel du Dépositaire central et des SGI intermédiaires","En réserve bloquée non utilisable sur un compte de l’AMF-UMOA"],"correct":1,"explication":"L’émission d’actions nouvelles injecte de l’argent frais dans la trésorerie et renforce les fonds propres de la société."},{"question":"Une société compte 8 millions d’actions et en émet 2 millions de nouvelles en bourse. Un actionnaire historique qui ne souscrit pas passe de 10 % du capital à :","options":["12,5 %","10,0 %","8,0 %","5,0 %"],"correct":2,"explication":"Il détenait 800 000 actions sur 8 M (10 %) ; après émission, il garde 800 000 actions sur 10 M au total, soit 8,0 % (dilution)."},{"question":"Quel engagement durable pèse sur une entreprise dès le premier jour de sa cotation ?","options":["Publier régulièrement des comptes audités et faits importants","Garantir un dividende fixe en croissance chaque trimestre","Racheter ses propres titres si le cours baisse sous le prix d’offre","Verser une prime annuelle à la BRVM proportionnelle au cours"],"correct":0,"explication":"La transparence périodique et permanente envers l’ensemble du marché devient une obligation continue de la société cotée."},{"question":"Que désigne habituellement une clause d’incessibilité (« lock-up ») signée par les fondateurs à l’occasion d’une IPO ?","options":["Un blocage temporaire empêchant les cédants de vendre le reste","Une garantie de prix plancher offerte par la BRVM pendant un an","L’obligation faite au public de conserver ses titres dix ans","L’interdiction de distribuer des dividendes pendant cinq exercices"],"correct":0,"explication":"Le lock-up rassure les nouveaux actionnaires en évitant qu’un actionnaire majoritaire n’inonde le marché juste après l’introduction."},{"question":"Quel coût spécifique faut-il intégrer lorsqu’une société prépare une introduction en bourse ?","options":["Les honoraires des conseils, des auditeurs et de la SGI chef de file","Le remboursement anticipé de l’ensemble de ses emprunts bancaires","Le paiement préalable des dividendes futurs sur cinq années","Une amende administrative perçue par les concurrents cotés"],"correct":0,"explication":"L’audit, le montage juridique, le syndicat de placement et la communication financière représentent un coût initial significatif."},{"question":"Une fois l’action admise sur le marché secondaire, comment évolue son cours par rapport au prix fixe de l’offre publique ?","options":["Il se fixe librement selon la confrontation des ordres quotidiens","Il reste bloqué au prix de souscription durant douze mois complets","Il progresse mécaniquement du taux d’intérêt directeur de la BCEAO","Il est recalculé une fois par an par l’AMF-UMOA après l’assemblée"],"correct":0,"explication":"Dès la première cotation, le prix résulte uniquement de l’offre et de la demande dans le carnet d’ordres de la BRVM."}],"liens":[{"label":"Les opérations sur titres","href":"/operations-titres"},{"label":"Les sociétés cotées","href":"/societes"},{"label":"L’agenda du marché","href":"/calendrier"}],"avertissement":"Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.","charts":[],"qcm":{"question":"Dans une offre publique de vente, à qui va l’argent des souscripteurs ?","options":["À la société","Aux actionnaires qui cèdent leurs titres","À la BRVM","À l’AMF-UMOA"],"correct":1,"explication":"Une OPV porte sur des actions existantes : le produit va aux vendeurs."},"exercice_id":"ecart-ipo-bbgc","nouveaute":{"type":"mis_a_jour","depuis":"2026-11-25"}}$n4_l4$::jsonb, true);
  IF NOT ((v_content->'lessons'->4->>'titre') LIKE 'Leçon 5 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : N4 position 4 inattendue (%)', v_content->'lessons'->4->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,4}', (v_content->'lessons'->4) || $n4_l5${"titre":"Leçon 5 — La procédure d’introduction à la BRVM","module":"Module 2 — Marché primaire et introduction en bourse","categorie":"regulatory","duree_min":10,"sous_titre":"De la décision des actionnaires à la première cotation : les étapes, les acteurs et les documents d’une introduction en bourse.","resume":"Une introduction en bourse suit une procédure encadrée. La société, accompagnée d’une SGI chef de file, prépare une note d’information que l’AMF-UMOA vise ; l’offre est ouverte au public ; les ordres sont alloués ; la BRVM admet ensuite les titres à la cote. Cette leçon détaille ces étapes et les documents que l’investisseur doit lire.","sections":[{"type":"definition","titre":"Les acteurs d’une introduction","contenu":"Une introduction en bourse réunit plusieurs acteurs, et chacun engage sa responsabilité sur une partie du processus.\nPour émettre des actions nouvelles, la société décide de l’opération en assemblée générale ; dans une offre publique de vente, ce sont les actionnaires vendeurs qui décident de céder leurs titres. Elle fournit ses comptes, décrit son activité et ses risques, et répond de l’exactitude des informations publiées. La SGI chef de file conduit l’opération : elle conseille la société, prépare le dossier avec elle, organise le placement auprès du public et centralise les ordres reçus par l’ensemble des SGI. D’autres conseils interviennent souvent : avocats, auditeurs, conseillers financiers.\nL’AMF-UMOA examine le dossier et vise la note d’information avant toute offre au public. La BRVM se prononce sur l’admission des titres à la cote, dans le compartiment qui correspond aux critères de la société, puis organise la première cotation.\nPour l’investisseur, la porte d’entrée reste sa SGI : c’est par elle que passe tout ordre de souscription, comme tout ordre de bourse.","points":[{"titre":"La société émettrice","detail":"Décide de l’opération en assemblée, fournit ses comptes et répond de l’exactitude des informations."},{"titre":"La SGI chef de file","detail":"Conduit l’opération, organise le placement auprès du public et centralise les ordres avec les autres SGI."},{"titre":"L’AMF-UMOA","detail":"Examine le dossier et vise la note d’information avant toute offre au public."},{"titre":"La BRVM","detail":"Se prononce sur l’admission des titres à la cote et organise la première cotation."}]},{"type":"importance","titre":"Les étapes","contenu":"L’ordre des étapes est constant ; leurs durées varient selon les opérations.\nLa préparation est la phase la plus longue et la moins visible. La société met ses comptes et sa gouvernance au niveau attendu d’une société cotée, choisit ses conseils et rédige avec eux la note d’information. Le dossier est ensuite déposé auprès de l’AMF-UMOA, qui peut demander des compléments avant d’accorder son visa.\nUne fois le visa obtenu, la période de souscription s’ouvre, pour une durée fixée dans la note d’information. Les investisseurs transmettent leurs ordres à leur SGI. À la clôture, la SGI chef de file centralise les demandes ; si elles dépassent l’offre, les ordres sont réduits selon les règles annoncées. Les résultats sont publiés, les titres livrés, et la BRVM organise la première séance de cotation.","etapes":[{"titre":"Décision et préparation","detail":"Assemblée générale, choix de la SGI chef de file et des conseils, audit des comptes."},{"titre":"Note d’information","detail":"Document décrivant la société, ses comptes, ses risques et l’opération."},{"titre":"Visa de l’AMF-UMOA","detail":"Aucune offre au public ne peut être ouverte avant ce visa.","cle":true},{"titre":"Période de souscription","detail":"Les investisseurs transmettent leurs ordres par l’intermédiaire d’une SGI."},{"titre":"Allocation et résultats","detail":"En cas de sursouscription, les ordres sont réduits selon les règles annoncées."},{"titre":"Admission et première cotation","detail":"La BRVM inscrit les titres à la cote ; les échanges commencent."}],"etapes_style":"frise"},{"type":"importance","titre":"Ce qu’il faut lire dans une note d’information","contenu":"C’est le seul document de référence de l’offre. Il est long : ces six rubriques suffisent à se faire une opinion.\nLa structure de l’opération dit qui vend, combien, et à qui va l’argent, comme on l’a vu à la leçon précédente. Les facteurs de risque sont rédigés par la société elle-même : ils sont parfois génériques, mais une société qui y signale une forte dépendance à un client ou à un contrat vous apprend quelque chose d’important.\nLes comptes historiques montrent la régularité des résultats sur plusieurs années, et permettent de vérifier que l’exercice qui sert de base au prix est représentatif. Le prix d’offre, rapporté au bénéfice et aux fonds propres, donne le PER et le P/B implicites. La politique de dividende dit ce que vous pouvez attendre en revenus ; les règles d’allocation, ce que vous recevrez réellement.","tableau":{"colonnes":["Rubrique","La question à se poser"],"lignes":[["Structure de l’opération","Qui vend, combien, et à qui va l’argent ?"],["Facteurs de risque","Qu’est-ce qui pourrait faire baisser les résultats ?"],["Comptes historiques","Le résultat est-il régulier sur plusieurs années ?"],["Prix et valorisation","Quel PER et quel P/B le prix d’offre implique-t-il ?"],["Politique de dividende","Un engagement de distribution est-il annoncé, et sur quelle base ?"],["Règles d’allocation","Comment les ordres seront-ils servis en cas de forte demande ?"]],"note":"Le visa de l’AMF-UMOA atteste que l’information est complète et compréhensible ; il ne juge pas l’intérêt de l’investissement."}},{"type":"piege","titre":"Les malentendus fréquents","contenu":"Trois idées fausses reviennent souvent, et chacune peut coûter cher.\nLe visa de l’AMF-UMOA n’est pas une recommandation. Il atteste que la note d’information est complète et compréhensible ; il ne dit pas que le prix est bon ni que l’opération est intéressante. Une société peut obtenir un visa et voir son cours baisser dès la première séance.\nSouscrire n’est pas recevoir. Exemple fictif : vous demandez 1 000 titres dans une offre souscrite à 200 %, avec une réduction proportionnelle. Chaque demande est servie à moitié : vous recevez 500 titres. D’autres règles existent, comme une priorité aux petits ordres ou à certaines catégories d’investisseurs : elles figurent dans la note.\nLe prix d’offre, enfin, n’est pas un plancher. Après la première cotation, le cours résulte de l’offre et de la demande, et peut passer sous le prix payé par les souscripteurs.","points":[{"titre":"Le visa n’est pas une recommandation","detail":"Il porte sur la qualité de l’information, pas sur l’opportunité d’acheter.","verifier":"La mention exacte du visa sur la note."},{"titre":"Souscrire n’est pas recevoir","detail":"En cas de sursouscription, vous ne recevez qu’une partie des titres demandés.","verifier":"Les règles d’allocation."},{"titre":"Le prix d’offre n’est pas un plancher","detail":"Après la première cotation, le cours peut passer sous le prix d’offre.","verifier":"La valorisation implicite du prix."}],"simulation":{"type":"souscription_ipo","consigne":"Testez la réduction proportionnelle sur une offre publique sursouscrite à 200 %.","titres_offerts":2000000,"prix":5000,"taux_souscription_pct":200,"demande":1000}},{"type":"retenir","titre":"L’essentiel","contenu":"Un visa, une note d’information, une SGI : trois repères qui structurent toute introduction en bourse.\nLa démarche de l’investisseur tient en quatre gestes : lire la structure de l’opération, lire les facteurs de risque, calculer la valorisation implicite du prix d’offre, et vérifier les règles d’allocation avant de décider combien demander. Le reste de la note se consulte selon les questions qui restent.","points":[{"titre":"Pas d’offre au public sans visa de l’AMF-UMOA"},{"titre":"La note d’information est le document de référence"},{"titre":"Les ordres passent par une SGI ; l’allocation peut les réduire"},{"titre":"Le visa atteste l’information, pas l’intérêt de l’investissement"}]}],"quiz":[{"question":"Quelle étape doit précéder toute offre au public ?","options":["La première cotation","Le visa de l’AMF-UMOA sur la note d’information","Le versement d’un dividende","L’allocation des titres"],"correct":1,"explication":"Aucune offre au public ne peut être ouverte avant le visa de l’AMF-UMOA."},{"question":"Que signifie le visa de l’AMF-UMOA ?","options":["Que l’investissement est recommandé","Que l’information est complète et compréhensible","Que le cours montera","Que la société est garantie par l’État"],"correct":1,"explication":"Le visa porte sur l’information, pas sur l’opportunité d’investir."},{"question":"Qui conduit l’opération et organise le placement auprès du public ?","options":["La BCEAO","La SGI chef de file","Le Dépositaire central","Chaque investisseur"],"correct":1,"explication":"La SGI chef de file pilote l’opération et centralise les ordres."},{"question":"Vous demandez 1 000 titres dans une offre sursouscrite à 200 %, avec une réduction proportionnelle. Combien en recevez-vous ?","options":["250","500","1 000","2 000"],"correct":1,"explication":"À 200 %, chaque ordre est servi à moitié : 500 titres."},{"question":"Le cours peut-il passer sous le prix d’offre après la première cotation ?","options":["Non, jamais","Oui : le prix d’offre n’est pas un plancher","Seulement le premier jour","Seulement pour les PME"],"correct":1,"explication":"Après la cotation, le cours résulte de l’offre et de la demande."},{"question":"Dans le montage d’une introduction en bourse, que signifie un syndicat de placement agissant en « prise ferme » ou « garantie de bonne fin » ?","options":["Le syndicat s’engage à souscrire les titres éventuellement invendus","Les acheteurs particuliers promettent de ne jamais revendre leurs parts","La BRVM garantit que le cours doublera dès la première séance","L’État s’engage à racheter l’entreprise en cas de baisse du bénéfice"],"correct":0,"explication":"Contrairement au placement pour compte (« best efforts »), l’engagement de garantie sécurise la levée pour l’émetteur."},{"question":"Quelle section d’une note d’information visée mérite en priorité une lecture attentive pour identifier ce qui pourrait fragiliser l’opération ?","options":["La rubrique consacrée aux facteurs de risque et à l’usage des fonds","La page de couverture mentionnant le nom de l’imprimeur officiel","L’adresse postale des succursales bancaires recevant les bulletins","Le calendrier des jours fériés bancaires des dix prochains exercices"],"correct":0,"explication":"Les facteurs de risque, la méthode de valorisation et la destination précise des capitaux éclairent le profil réel de l’IPO."},{"question":"Que vérifie concrètement le visa apposé par l’AMF-UMOA sur la note d’information ?","options":["Que l’information présentée est complète, cohérente et compréhensible","Que le prix d’introduction retenu est mathématiquement sous-évalué","Que la société versera à coup sûr un dividende dès l’année suivante","Que le titre sera automatiquement intégré au BRVM 30 dès le premier jour"],"correct":0,"explication":"Le visa porte sur la qualité et la sincérité de l’information divulguée ; il ne constitue jamais une appréciation d’opportunité financière."},{"question":"Pourquoi la période de centralisation des ordres prend-elle plusieurs jours entre la clôture de l’offre et la première cotation ?","options":["Pour agréger toutes les demandes des SGI et appliquer les allocations","Pour laisser le temps aux dirigeants de modifier le prix de l’offre","Pour verser un premier acompte sur dividende avant même l’ouverture","Pour convertir l’ensemble des ordres en devises étrangères hors UEMOA"],"correct":0,"explication":"Le chef de file consolide les souscriptions du réseau, calcule la réduction éventuelle et transmet les titres attribués au DC/BR."},{"question":"Lorsque votre ordre de souscription est réduit de moitié dans une offre sursouscrite, qu’advient-il de la somme versée en trop à votre SGI ?","options":["Le reliquat de trésorerie est restitué sur votre compte espèces","La différence est conservée par la BRVM à titre de commission fixe","Le montant est converti automatiquement en actions d’une autre banque","La somme reste bloquée pendant cinq ans sans produire aucun intérêt"],"correct":0,"explication":"Vous ne réglez finalement que les titres effectivement servis ; l’excédent bloqué lors de la souscription vous est débloqué."}],"liens":[{"label":"Les opérations sur titres","href":"/operations-titres"},{"label":"Choisir sa SGI","href":"/comparateur-sgi"},{"label":"Les fondamentaux","href":"/fondamentaux"}],"avertissement":"Ceci n’est pas un conseil en investissement ni un avis juridique. Les règles citées sont résumées ; seuls les textes officiels de l’AMF-UMOA et de la BRVM font foi.","charts":[],"qcm":{"question":"Quelle étape doit précéder toute offre au public ?","options":["La première cotation","Le visa de l’AMF-UMOA sur la note d’information","Le versement d’un dividende","L’allocation des titres"],"correct":1,"explication":"Aucune offre au public ne peut être ouverte avant le visa de l’AMF-UMOA."},"nouveaute":{"type":"mis_a_jour","depuis":"2026-11-25"}}$n4_l5$::jsonb, true);
  UPDATE public.academy_courses SET content = v_content, updated_at = now() WHERE slug = 'academy-niveau-4-expert';

  -- 3. Rattachement exercice_id sur Niveaux 1, 2 et 3
  SELECT content INTO v_content FROM public.academy_courses WHERE slug = 'academy-niveau-1-initiation' FOR UPDATE;
  IF v_content IS NULL THEN RAISE EXCEPTION 'Cours academy-niveau-1-initiation introuvable'; END IF;
  IF NOT ((v_content->'lessons'->0->>'titre') LIKE 'Leçon 1 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-1-initiation position 0 inattendue (%)', v_content->'lessons'->0->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,0,exercice_id}', '"capitalisation-du-jour"'::jsonb, true);
  IF NOT ((v_content->'lessons'->2->>'titre') LIKE 'Leçon 3 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-1-initiation position 2 inattendue (%)', v_content->'lessons'->2->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,2,exercice_id}', '"cout-ordre-du-jour"'::jsonb, true);
  IF NOT ((v_content->'lessons'->3->>'titre') LIKE 'Leçon 4 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-1-initiation position 3 inattendue (%)', v_content->'lessons'->3->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,3,exercice_id}', '"rendement-net"'::jsonb, true);
  UPDATE public.academy_courses SET content = v_content, updated_at = now() WHERE slug = 'academy-niveau-1-initiation';

  SELECT content INTO v_content FROM public.academy_courses WHERE slug = 'academy-niveau-2-fondamental' FOR UPDATE;
  IF v_content IS NULL THEN RAISE EXCEPTION 'Cours academy-niveau-2-fondamental introuvable'; END IF;
  IF NOT ((v_content->'lessons'->9->>'titre') LIKE 'Leçon 2 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-2-fondamental position 9 inattendue (%)', v_content->'lessons'->9->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,9,exercice_id}', '"per-du-jour"'::jsonb, true);
  IF NOT ((v_content->'lessons'->10->>'titre') LIKE 'Leçon 3 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-2-fondamental position 10 inattendue (%)', v_content->'lessons'->10->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,10,exercice_id}', '"value-trap-pick"'::jsonb, true);
  UPDATE public.academy_courses SET content = v_content, updated_at = now() WHERE slug = 'academy-niveau-2-fondamental';

  SELECT content INTO v_content FROM public.academy_courses WHERE slug = 'academy-niveau-3-technique' FOR UPDATE;
  IF v_content IS NULL THEN RAISE EXCEPTION 'Cours academy-niveau-3-technique introuvable'; END IF;
  IF NOT ((v_content->'lessons'->1->>'titre') LIKE 'Leçon 1 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-3-technique position 1 inattendue (%)', v_content->'lessons'->1->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,1,exercice_id}', '"variation-20-seances"'::jsonb, true);
  IF NOT ((v_content->'lessons'->3->>'titre') LIKE 'Leçon 3 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-3-technique position 3 inattendue (%)', v_content->'lessons'->3->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,3,exercice_id}', '"position-moyenne-20"'::jsonb, true);
  IF NOT ((v_content->'lessons'->4->>'titre') LIKE 'Leçon 4 — %') THEN
    RAISE EXCEPTION 'Migration 0270 : academy-niveau-3-technique position 4 inattendue (%)', v_content->'lessons'->4->>'titre';
  END IF;
  v_content := jsonb_set(v_content, '{lessons,4,exercice_id}', '"rsi-zone-du-jour"'::jsonb, true);
  UPDATE public.academy_courses SET content = v_content, updated_at = now() WHERE slug = 'academy-niveau-3-technique';

END $$;

-- 4. Synchronisation idempotente de academy_exam_questions (debutant Module 1 + expert 52 Q)
INSERT INTO public.academy_exam_questions (niveau, question, options, correct, explication, source, active)
SELECT v.niveau, v.question, v.options, v.correct, v.explication, 'quiz', true
FROM (VALUES
  ($q_n_0$debutant$q_n_0$, $q_q_0$Combien de pays partagent la BRVM ?$q_q_0$, $q_o_0$["Trois pays","Cinq pays","Huit pays","Quinze pays"]$q_o_0$::jsonb, 2, $q_e_0$La BRVM est commune aux huit pays de l’UEMOA : Bénin, Burkina Faso, Côte d’Ivoire, Guinée-Bissau, Mali, Niger, Sénégal et Togo.$q_e_0$),
  ($q_n_1$debutant$q_n_1$, $q_q_1$Qui supervise le marché financier régional et agrée les intermédiaires ?$q_q_1$, $q_o_1$["La BRVM elle-même","L’AMF-UMOA","Chaque SGI en autonomie","Les banques centrales nationales"]$q_o_1$::jsonb, 1, $q_e_1$L’Autorité des Marchés Financiers de l’UMOA (qui a succédé au CREPMF) agrée les intermédiaires, contrôle le marché et protège les investisseurs.$q_e_1$),
  ($q_n_2$debutant$q_n_2$, $q_q_2$Pour acheter une action cotée à la BRVM, par qui un particulier doit-il obligatoirement passer ?$q_q_2$, $q_o_2$["Directement par le site de la BRVM","Par une SGI agréée","Par le siège de la société cotée","Par un groupe de conseil sur messagerie"]$q_o_2$::jsonb, 1, $q_e_2$Seules les Sociétés de Gestion et d’Intermédiation agréées ont accès au système de cotation de la BRVM pour transmettre vos ordres.$q_e_2$),
  ($q_n_3$debutant$q_n_3$, $q_q_3$Le BRVM Composite termine une année exactement à 0 %. Les actionnaires ont-ils forcément gagné 0 % ?$q_q_3$, $q_o_3$["Oui, l’indice inclut tous les gains","Non : il ignore les dividendes","Non : il exclut les valeurs ivoiriennes","Oui, sauf en cas de hausse des taux"]$q_o_3$::jsonb, 1, $q_e_3$Le BRVM Composite et le BRVM 30 sont des indices de prix nus : les dividendes versés par les entreprises n’y entrent pas.$q_e_3$),
  ($q_n_4$debutant$q_n_4$, $q_q_4$Lequel de ces droits une action ne donne-t-elle PAS ?$q_q_4$, $q_o_4$["Voter en assemblée générale","Percevoir le dividende voté","Revendre ses titres en séance","Un revenu garanti chaque année"]$q_o_4$::jsonb, 3, $q_e_4$Le dividende dépend des bénéfices et du vote annuel de l’assemblée générale : il n’est jamais garanti.$q_e_4$),
  ($q_n_5$debutant$q_n_5$, $q_q_5$Quelle est la limite habituelle de variation du cours d’une action au cours d’une même séance BRVM (hors ajustement technique) ?$q_q_5$, $q_o_5$["±7,5 %","±2,0 %","±25,0 %","Aucune limite"]$q_o_5$::jsonb, 0, $q_e_5$La BRVM encadre la variation quotidienne à ±7,5 % autour du cours de référence pour amortir les chocs sur un marché étroit.$q_e_5$),
  ($q_n_6$debutant$q_n_6$, $q_q_6$Une action A cote 52 FCFA et une action B cote 42 000 FCFA. Que peut-on en déduire sur la taille des deux entreprises ?$q_q_6$, $q_o_6$["L’entreprise B est forcément plus grande","L’entreprise A est en difficulté financière","Rien sans connaître leur nombre d’actions","L’action A est huit cents fois moins chère à l’achat"]$q_o_6$::jsonb, 2, $q_e_6$La taille boursière est la capitalisation (cours × nombre d’actions). Au 24/11/2026, ETIT à 52 FCFA vaut 940,4 Md FCFA contre 385,7 Md FCFA pour UNLC à 42 000 FCFA.$q_e_6$),
  ($q_n_7$debutant$q_n_7$, $q_q_7$Dans quel délai habituel s’effectue le règlement-livraison (échange titres contre espèces) après une exécution à la BRVM ?$q_q_7$, $q_o_7$["Instantanément dans la minute","En trois jours ouvrés (J+3)","À la fin de chaque mois civil","Après la prochaine assemblée générale"]$q_o_7$::jsonb, 1, $q_e_7$Le dénouement titres contre espèces par le Dépositaire Central (DC/BR) intervient en J+3 ouvrés après la séance d’exécution.$q_e_7$),
  ($q_n_8$debutant$q_n_8$, $q_q_8$Que révèle la mesure réelle de la liquidité à la BRVM sur fin 2026 ?$q_q_8$, $q_o_8$["Les 48 titres s’échangent à parts égales","Les dix titres les plus actifs concentrent plus de 70 % des échanges","Seules les obligations sont réellement échangées","Aucune action ne dépasse 5 % des volumes"]$q_o_8$::jsonb, 1, $q_e_8$Sur 65 séances (24/08 au 23/11/2026), les 10 valeurs les plus échangées représentent 71,9 % des capitaux échangés (dont 40,9 % pour Sonatel seule).$q_e_8$),
  ($q_n_9$debutant$q_n_9$, $q_q_9$Une action affiche 0 % de variation pendant trois séances d’affilée à la BRVM. Quelle est l’explication la plus fréquente ?$q_q_9$, $q_o_9$["Son cours est figé par le régulateur","Aucun échange n’a eu lieu sur ces séances","La société prépare une fusion imminente","Les dividendes sont en cours de calcul"]$q_o_9$::jsonb, 1, $q_e_9$Sur les valeurs peu liquides, il arrive fréquemment qu’aucun ordre d’achat ne croise un ordre de vente durant une ou plusieurs séances : le cours reste alors inchangé.$q_e_9$),
  ($q_n_10$debutant$q_n_10$, $q_q_10$Votre dividende n’est pas arrivé cinq jours après la date de paiement. Qui contactez-vous en premier ?$q_q_10$, $q_o_10$["La BRVM","L’AMF-UMOA","Votre SGI","La société cotée"]$q_o_10$::jsonb, 2, $q_e_10$Votre SGI tient votre compte-titres et votre compte espèces : elle seule peut vérifier l’imputation sur votre compte. L’AMF-UMOA n’intervient qu’en dernier recours.$q_e_10$),
  ($q_n_11$debutant$q_n_11$, $q_q_11$Quel acteur agrée les SGI, homologue leurs tarifs et sanctionne les abus ?$q_q_11$, $q_o_11$["La BRVM","L’AMF-UMOA","Le DC/BR","La société cotée"]$q_o_11$::jsonb, 1, $q_e_11$L’Autorité des Marchés Financiers de l’UMOA, qui a succédé au CREPMF, est le régulateur public du marché financier régional.$q_e_11$),
  ($q_n_12$debutant$q_n_12$, $q_q_12$Quel est le rôle principal du DC/BR ?$q_q_12$, $q_o_12$["Fixer le prix quotidien des actions","Tenir les titres et régler les échanges","Démarcher les épargnants particuliers","Voter les dividendes des entreprises"]$q_o_12$::jsonb, 1, $q_e_12$Le Dépositaire Central / Banque de Règlement tient le registre central dématérialisé et assure le règlement-livraison (titres contre espèces) à J+3.$q_e_12$),
  ($q_n_13$debutant$q_n_13$, $q_q_13$Un « conseiller » vous propose sur WhatsApp un placement BRVM garanti à 15 % par mois via Mobile Money. Que faites-vous ?$q_q_13$, $q_o_13$["Vous testez avec une petite somme","Vous refusez : c’est une arnaque","Vous demandez son attestation PDF","Vous négociez les frais d’entrée"]$q_o_13$::jsonb, 1, $q_e_13$Un gain élevé garanti et un versement hors compte professionnel d’une SGI agréée sont des signaux caractéristiques d’escroquerie.$q_e_13$),
  ($q_n_14$debutant$q_n_14$, $q_q_14$Où sont juridiquement conservés les titres que vous achetez à la BRVM ?$q_q_14$, $q_o_14$["Inscrits en compte-titres et enregistrés au DC/BR","Imprimés sur certificat papier envoyé par poste","Déposés dans les coffres de la société cotée","Fusionnés dans votre compte courant bancaire"]$q_o_14$::jsonb, 0, $q_e_14$Les titres sont dématérialisés : inscrits sur votre compte-titres chez votre SGI et enregistrés de façon ségréguée au DC/BR.$q_e_14$),
  ($q_n_15$debutant$q_n_15$, $q_q_15$Que se passe-t-il pour vos actions si votre SGI fait faillite ou perd son agrément ?$q_q_15$, $q_o_15$["Elles servent à rembourser les créanciers de la SGI","Vos titres restent votre propriété et sont transférés","La BRVM indemnise uniquement la moitié de leur valeur","Vous perdez définitivement vos droits aux dividendes"]$q_o_15$::jsonb, 1, $q_e_15$Grâce à la ségrégation des avoirs au DC/BR, vos titres ne font pas partie du bilan de la SGI : ils restent votre propriété et sont transférables vers une autre SGI agréée.$q_e_15$),
  ($q_n_16$debutant$q_n_16$, $q_q_16$Que signifie un visa délivré par l’AMF-UMOA sur une note d’information d’introduction en bourse ?$q_q_16$, $q_o_16$["Le régulateur garantit la hausse future du titre","L’information publiée est conforme et complète","L’État couvre les pertes éventuelles des souscripteurs","Les dividendes sont assurés pendant cinq exercices"]$q_o_16$::jsonb, 1, $q_e_16$Le visa porte uniquement sur la conformité et la transparence de l’information fournie au public, jamais sur la rentabilité future de l’opération.$q_e_16$),
  ($q_n_17$debutant$q_n_17$, $q_q_17$Un résident du Mali ou de la diaspora européenne peut-il ouvrir un compte dans une SGI basée en Côte d’Ivoire ou au Sénégal ?$q_q_17$, $q_o_17$["Non, seule une SGI de son pays de résidence est autorisée","Oui, la zone UEMOA forme un marché unique","Oui, mais uniquement pour souscrire à des emprunts publics","Non, sauf dérogation individuelle délivrée par la BRVM"]$q_o_17$::jsonb, 1, $q_e_17$Le marché est régional : vous pouvez choisir n’importe quelle SGI agréée de l’UEMOA qui accepte votre dossier et vos justificatifs d’identité.$q_e_17$),
  ($q_n_18$debutant$q_n_18$, $q_q_18$Quel document officiel prouve le prix exact exécuté et le détail des frais payés après un ordre ?$q_q_18$, $q_o_18$["Le Bulletin officiel de la cote du soir","L’avis d’opéré remis par votre SGI","Le rapport annuel de la société cotée","Le reçu bancaire de votre dernier virement"]$q_o_18$::jsonb, 1, $q_e_18$Après chaque exécution, votre SGI émet un avis d’opéré détaillant la quantité, le cours d’exécution, le courtage, les commissions de marché et les taxes.$q_e_18$),
  ($q_n_19$debutant$q_n_19$, $q_q_19$Quel acteur gère des fonds collectifs diversifiés (FCP, SICAV) investis à la BRVM ?$q_q_19$, $q_o_19$["Une SGO (Société de Gestion d’OPCVM)","Le Dépositaire Central (DC/BR)","Une Antenne Nationale de Bourse","Le greffe du tribunal de commerce"]$q_o_19$::jsonb, 0, $q_e_19$Les SGO agréées par l’AMF-UMOA créent et gèrent les OPCVM (FCP et SICAV) pour les épargnants qui souhaitent déléguer la sélection et la diversification.$q_e_19$),
  ($q_n_20$debutant$q_n_20$, $q_q_20$Une action cote 2 500 FCFA. Vous en achetez 10, avec 1 % de frais (sans minimum). Combien payez-vous ?$q_q_20$, $q_o_20$["2 525 FCFA","25 000 FCFA","25 250 FCFA","27 500 FCFA"]$q_o_20$::jsonb, 2, $q_e_20$10 × 2 500 = 25 000 FCFA, plus 1 % de frais, soit 250 FCFA : 25 250 FCFA au total.$q_e_20$),
  ($q_n_21$debutant$q_n_21$, $q_q_21$Vos frais sont de 1,5 % à l’achat et 1,5 % à la revente. De combien l’action doit-elle monter, environ, pour que l’opération ne perde rien ?$q_q_21$, $q_o_21$["0,75 %","1,5 %","3 %","15 %"]$q_o_21$::jsonb, 2, $q_e_21$Les frais se paient deux fois : 1,5 % à l’achat + 1,5 % à la revente = environ 3 %. En dessous, l’aller-retour est perdant.$q_e_21$),
  ($q_n_22$debutant$q_n_22$, $q_q_22$Une action cote 1 800 FCFA, une autre 30 000 FCFA. Que peut-on en conclure ?$q_q_22$, $q_o_22$["La première est la meilleure affaire","La seconde est de meilleure qualité","Rien sans analyser leurs fondamentaux","La première verse un plus petit dividende"]$q_o_22$::jsonb, 2, $q_e_22$Le cours d’une action dépend du nombre de titres en circulation, pas de sa cherté ni de sa qualité. Il faut rapporter le prix aux bénéfices ou aux dividendes.$q_e_22$),
  ($q_n_23$debutant$q_n_23$, $q_q_23$50 000 FCFA répartis à parts égales sur cinq valeurs. L’une d’elles baisse de 20 %. Combien perd le portefeuille ?$q_q_23$, $q_o_23$["10 000 FCFA","2 000 FCFA","4 000 FCFA","20 000 FCFA"]$q_o_23$::jsonb, 1, $q_e_23$Chaque ligne vaut 10 000 FCFA ; 20 % de 10 000 = 2 000 FCFA, soit 4 % du portefeuille. Sur une seule valeur, la perte aurait été de 10 000 FCFA.$q_e_23$),
  ($q_n_24$debutant$q_n_24$, $q_q_24$Pourquoi éviter de multiplier les très petits ordres quand votre SGI applique un minimum de perception ?$q_q_24$, $q_o_24$["La BRVM refuse les ordres sous dix titres","Le minimum de frais pèse très lourd en %","Ils ne donnent pas droit au dividende","Ils sont exécutés seulement le vendredi"]$q_o_24$::jsonb, 1, $q_e_24$Un minimum de 2 500 FCFA sur un ordre de 10 000 FCFA représente 25 % de frais dès l’achat (50 % aller-retour). Mieux vaut regrouper son épargne.$q_e_24$),
  ($q_n_25$debutant$q_n_25$, $q_q_25$Votre SGI facture 10 000 FCFA de frais fixes de tenue de compte par an. Combien cela représente-t-il sur un portefeuille de 50 000 FCFA ?$q_q_25$, $q_o_25$["20 % par an","2 % par an","5 % par an","0,5 % par an"]$q_o_25$::jsonb, 0, $q_e_25$10 000 ÷ 50 000 = 20 % par an : ces frais fixes absorberaient plus que les dividendes habituels. Sur un petit budget, il faut cibler une SGI sans frais fixes lourds.$q_e_25$),
  ($q_n_26$debutant$q_n_26$, $q_q_26$À la BRVM, quel est le montant minimum fixé par la loi pour acheter des actions ?$q_q_26$, $q_o_26$["Aucun : le prix d’une seule action entière","100 000 FCFA obligatoires","500 000 FCFA fixés par la BRVM","1 000 000 FCFA fixés par l’AMF-UMOA"]$q_o_26$::jsonb, 0, $q_e_26$La BRVM ne fixe aucun plancher en FCFA : on achète au minimum une action entière. Le dépôt minimum éventuel dépend uniquement de la politique commerciale de chaque SGI.$q_e_26$),
  ($q_n_27$debutant$q_n_27$, $q_q_27$Quel repère de diversification est retenu dans l’Académie pour limiter le risque de concentration ?$q_q_27$, $q_o_27$["Max 50 % par titre et 80 % par secteur","Max 20 % par société et 35 % par secteur","Exactement 100 % sur le secteur bancaire","Uniquement des titres sous 2 000 FCFA"]$q_o_27$::jsonb, 1, $q_e_27$Limiter chaque société à 20 % et chaque secteur à 35 % évite qu’un choc isolé ou sectoriel ne mette en danger tout votre capital.$q_e_27$),
  ($q_n_28$debutant$q_n_28$, $q_q_28$Que faut-il constituer AVANT d’investir son premier franc en actions ?$q_q_28$, $q_o_28$["Un crédit bancaire à taux variable","Une épargne de précaution disponible","Un compte dans trois SGI différentes","Un portefeuille d’au moins vingt titres"]$q_o_28$::jsonb, 1, $q_e_28$Disposer de 3 à 6 mois de dépenses courantes sur un support liquide évite d’être forcé de vendre vos actions en pleine baisse lors d’un imprévu.$q_e_28$),
  ($q_n_29$debutant$q_n_29$, $q_q_29$Vous épargnez 20 000 FCFA par mois chez une SGI qui applique un minimum de 2 000 FCFA par ordre. Quelle pratique réduit vos frais ?$q_q_29$, $q_o_29$["Passer quatre ordres de 5 000 FCFA","Cumuler 4 à 6 mois avant d’acheter","Vendre et racheter chaque semaine","Emprunter pour acheter plus vite"]$q_o_29$::jsonb, 1, $q_e_29$En cumulant 100 000 à 120 000 FCFA sur votre compte espèces avant de passer l’ordre, le minimum de 2 000 FCFA retombe sous 2 % au lieu de 10 % sur 20 000 FCFA.$q_e_29$),
  ($q_n_30$debutant$q_n_30$, $q_q_30$Vous achetez 200 actions à 5 000 FCFA et les revendez à 5 600 FCFA. Quelle est votre plus-value, hors frais ?$q_q_30$, $q_o_30$["600 FCFA","12 000 FCFA","120 000 FCFA","1 120 000 FCFA"]$q_o_30$::jsonb, 2, $q_e_30$(5 600 − 5 000) × 200 = 600 × 200 = 120 000 FCFA.$q_e_30$),
  ($q_n_31$debutant$q_n_31$, $q_q_31$Vous avez investi 1 000 000 FCFA, reçu 80 000 FCFA de dividendes et réalisé 120 000 FCFA de plus-value. Quel est votre rendement total ?$q_q_31$, $q_o_31$["8 %","12 %","20 %","200 %"]$q_o_31$::jsonb, 2, $q_e_31$(80 000 + 120 000) ÷ 1 000 000 = 200 000 ÷ 1 000 000 = 20 %.$q_e_31$),
  ($q_n_32$debutant$q_n_32$, $q_q_32$Une société lance une augmentation de capital avec DPS. Quel choix fait perdre de l’argent à coup sûr ?$q_q_32$, $q_o_32$["Exercer tous ses DPS","Céder ses DPS sur le marché","Les laisser expirer sans agir","Vendre une part et exercer l’autre"]$q_o_32$::jsonb, 2, $q_e_32$À la fin de la période de souscription, les droits non utilisés tombent à zéro : vous subissez la dilution du cours sans aucune compensation.$q_e_32$),
  ($q_n_33$debutant$q_n_33$, $q_q_33$Vous achetez une action la veille du détachement, uniquement pour toucher le dividende. Que se passe-t-il le lendemain ?$q_q_33$, $q_o_33$["Vous gagnez le dividende sans contrepartie","Le cours s’ajuste à la baisse du dividende","Votre SGI annule automatiquement l’ordre","La société rembourse vos frais d’achat"]$q_o_33$::jsonb, 1, $q_e_33$Au détachement (comme sur FTSC le 26/09/2025), le cours baisse d’environ le montant du dividende. Le gain apparent est compensé et les frais restent à votre charge.$q_e_33$),
  ($q_n_34$debutant$q_n_34$, $q_q_34$Une société a versé un dividende chaque année depuis dix ans. Que pouvez-vous en déduire ?$q_q_34$, $q_o_34$["Le dividende est garanti à vie","Il peut baisser ou disparaître","Il augmentera forcément l’an prochain","L’AMF-UMOA interdit de le réduire"]$q_o_34$::jsonb, 1, $q_e_34$La régularité passée est un indice de discipline, jamais une garantie : chaque année, l’assemblée générale vote en fonction des résultats réels.$q_e_34$),
  ($q_n_35$debutant$q_n_35$, $q_q_35$Quel pays détermine le taux d’impôt retenu à la source (IRVM) sur un dividende BRVM ?$q_q_35$, $q_o_35$["Le pays où siège la société cotée","Le pays où réside l’actionnaire","Toujours la Côte d’Ivoire (siège BRVM)","Le pays où est située votre SGI"]$q_o_35$::jsonb, 0, $q_e_35$L’IRVM est prélevé à la source selon la fiscalité du pays de l’émetteur (par exemple 10 % au Sénégal, 12 % en Côte d’Ivoire pour les particuliers depuis 2025, 3 % au Togo).$q_e_35$),
  ($q_n_36$debutant$q_n_36$, $q_q_36$Quelle date devez-vous surveiller pour savoir si votre achat vous donne droit au dividende de l’exercice ?$q_q_36$, $q_o_36$["La date de détachement (ex-dividende)","La date de paiement sur votre compte","Le 31 décembre de l’année suivante","La date de publication du rapport annuel"]$q_o_36$::jsonb, 0, $q_e_36$Il faut détenir le titre avant la date de détachement. Un achat effectué le jour du détachement ou après ne donne plus droit au dividende de l’exercice.$q_e_36$),
  ($q_n_37$debutant$q_n_37$, $q_q_37$Sur quel compte votre SGI verse-t-elle un dividende en espèces ?$q_q_37$, $q_o_37$["Sur le compte espèces associé","Sur le compte-titres en actions","Sur un compte bloqué au DC/BR","Directement chez la BRVM"]$q_o_37$::jsonb, 0, $q_e_37$Les dividendes en numéraire sont toujours crédités en francs CFA sur le compte espèces lié à votre compte-titres.$q_e_37$),
  ($q_n_38$debutant$q_n_38$, $q_q_38$Pourquoi les DPS reçus lors d’une augmentation de capital ne constituent-ils pas une « troisième source de gain » ?$q_q_38$, $q_o_38$["Ils sont interdits aux particuliers","Ils compensent seulement la dilution","Ils ne peuvent jamais être vendus","Ils sont taxés à 100 % à la source"]$q_o_38$::jsonb, 1, $q_e_38$La valeur des DPS correspond à la baisse technique du cours au détachement : les vendre ou les exercer préserve votre patrimoine mais ne crée pas de gain nouveau.$q_e_38$),
  ($q_n_39$debutant$q_n_39$, $q_q_39$Une action achetée 10 000 FCFA vaut aujourd’hui 13 000 FCFA, mais vous ne l’avez pas vendue. De quoi s’agit-il ?$q_q_39$, $q_o_39$["D’un dividende exceptionnel acquis","D’une plus-value latente (non réalisée)","D’un gain définitivement garanti","D’un droit préférentiel de souscription"]$q_o_39$::jsonb, 1, $q_e_39$Tant que la vente n’est pas exécutée, le gain reste latent : une baisse ultérieure du cours peut le réduire ou l’effacer.$q_e_39$),
  ($q_n_40$expert$q_n_40$, $q_q_40$Quelle institution a succédé à l’ex-CREPMF ?$q_q_40$, $q_o_40$["La BCEAO","L’AMF-UMOA","La BRVM","La Commission bancaire"]$q_o_40$::jsonb, 1, $q_e_40$L’AMF-UMOA a succédé au CREPMF le 1er octobre 2022, à l’entrée en vigueur du Traité révisé de l’UMOA.$q_e_40$),
  ($q_n_41$expert$q_n_41$, $q_q_41$Qui est seul habilité à négocier vos ordres en bourse ?$q_q_41$, $q_o_41$["Votre banque, quelle qu’elle soit","Une SGI agréée","La BRVM directement","Le Dépositaire central"]$q_o_41$::jsonb, 1, $q_e_41$Les ordres de bourse passent obligatoirement par une SGI agréée.$q_e_41$),
  ($q_n_42$expert$q_n_42$, $q_q_42$Quel est le rôle du Dépositaire central / Banque de règlement ?$q_q_42$, $q_o_42$["Fixer les cours","Conserver les titres et régler les transactions","Agréer les SGI","Publier les comptes des sociétés"]$q_o_42$::jsonb, 1, $q_e_42$Il assure la conservation centrale des titres, le règlement et la livraison.$q_e_42$),
  ($q_n_43$expert$q_n_43$, $q_q_43$La BRVM garantit-elle la solidité des sociétés cotées ?$q_q_43$, $q_o_43$["Oui, elle garantit toutes les sociétés cotées","Non : elle organise la cotation","Oui, pour le compartiment Prestige","Seulement pour les banques cotées"]$q_o_43$::jsonb, 1, $q_e_43$La cotation n’est pas une garantie : l’investisseur reste exposé au risque de la société.$q_e_43$),
  ($q_n_44$expert$q_n_44$, $q_q_44$Quel organe la réforme de 2022 a-t-elle créé au sein de l’AMF-UMOA ?$q_q_44$, $q_o_44$["Une banque centrale","Une Commission des sanctions","Une nouvelle bourse","Un fonds de garantie des dépôts"]$q_o_44$::jsonb, 1, $q_e_44$La réforme a doté l’AMF-UMOA d’une Commission des sanctions et d’un Médiateur.$q_e_44$),
  ($q_n_45$expert$q_n_45$, $q_q_45$À quelle date l’AMF-UMOA a-t-elle officiellement succédé à l’ex-CREPMF ?$q_q_45$, $q_o_45$["Le 1er janvier 1998","Le 1er octobre 2022","Le 15 mars 2015","Le 1er juillet 2024"]$q_o_45$::jsonb, 1, $q_e_45$Le Traité révisé de l’UMOA entré en vigueur le 1er octobre 2022 a transformé l’ex-CREPMF en AMF-UMOA.$q_e_45$),
  ($q_n_46$expert$q_n_46$, $q_q_46$Pourquoi les espèces et titres des clients sont-ils cantonnés au DC/BR séparément des fonds propres de la SGI ?$q_q_46$, $q_o_46$["Pour protéger les avoirs des clients en cas de défaut de la SGI","Pour augmenter le dividende versé chaque année aux actionnaires","Pour permettre à la BRVM de fixer des cours sans carnet d’ordres","Pour dispenser les particuliers de tout prélèvement fiscal IRVM"]$q_o_46$::jsonb, 0, $q_e_46$La ségrégation des comptes au DC/BR isole les titres et avoirs des clients du bilan propre de l’intermédiaire.$q_e_46$),
  ($q_n_47$expert$q_n_47$, $q_q_47$Quelle mission relève directement de la Bourse Régionale des Valeurs Mobilières (BRVM) ?$q_q_47$, $q_o_47$["La politique monétaire des huit États de l’UEMOA","L’organisation des séances de cotation et du carnet","La gestion individuelle des portefeuilles des particuliers","Le prélèvement de l’impôt sur le revenu des sociétés"]$q_o_47$::jsonb, 1, $q_e_47$La BRVM organise la cotation centralisée, la diffusion des cours officiels et la surveillance technique des séances.$q_e_47$),
  ($q_n_48$expert$q_n_48$, $q_q_48$Un épargnant souhaite déposer une réclamation après un litige avec sa SGI. Quel recours interne existe depuis la réforme de 2022 ?$q_q_48$, $q_o_48$["Le Médiateur institué auprès de l’AMF-UMOA","La chambre commerciale du Fonds monétaire international","L’assemblée générale annuelle des sociétés du compartiment","Le service client de la Bourse de Dakar uniquement"]$q_o_48$::jsonb, 0, $q_e_48$La réforme instituant l’AMF-UMOA a mis en place un Médiateur chargé de traiter les différends entre épargnants et intervenants agréés.$q_e_48$),
  ($q_n_49$expert$q_n_49$, $q_q_49$Qui délivre l’agrément indispensable pour exercer en tant que SGI dans l’espace UEMOA ?$q_q_49$, $q_o_49$["L’AMF-UMOA, autorité de régulation du marché financier","La chambre de commerce du pays du demandeur","Le conseil d’administration de chaque société cotée","La première SGI historique implantée à Abidjan"]$q_o_49$::jsonb, 0, $q_e_49$Seule l’AMF-UMOA délivre l’agrément aux SGI, sociétés de gestion d’OPCVM et autres acteurs du marché financier régional.$q_e_49$),
  ($q_n_50$expert$q_n_50$, $q_q_50$Que se passe-t-il durant l’étape de règlement-livraison pilotée par le DC/BR après exécution d’un achat ?$q_q_50$, $q_o_50$["La SGI conserve les titres en papier dans ses propres coffres","Les titres sont virés au compte de l’acheteur contre espèces","La société émettrice verse immédiatement un dividende spécial","Le prix exécuté est recalculé selon la séance du lendemain"]$q_o_50$::jsonb, 1, $q_e_50$Le DC/BR garantit la livraison simultanée des titres sur le compte-titres de l’acheteur contre le règlement en espèces.$q_e_50$),
  ($q_n_51$expert$q_n_51$, $q_q_51$Quels sont les trois caractères d’une information privilégiée ?$q_q_51$, $q_o_51$["Ancienne, publique, sans effet","Précise, non publique, susceptible d’influencer le cours","Vague, publique, chiffrée","Officielle, ancienne, confidentielle"]$q_o_51$::jsonb, 1, $q_e_51$Une information privilégiée est précise, non encore publique, et susceptible d’influencer sensiblement le cours.$q_e_51$),
  ($q_n_52$expert$q_n_52$, $q_q_52$Une société signe un contrat majeur. Que lui impose l’information permanente ?$q_q_52$, $q_o_52$["D’attendre la publication du rapport annuel","De le rendre public sans délai","De n’en parler qu’aux grands actionnaires","Rien tant que le contrat n’est pas exécuté"]$q_o_52$::jsonb, 1, $q_e_52$Tout fait susceptible d’influencer sensiblement le cours doit être publié sans délai.$q_e_52$),
  ($q_n_53$expert$q_n_53$, $q_q_53$Des achats répétés en fin de séance pour gonfler le cours de clôture relèvent :$q_q_53$, $q_o_53$["D’une stratégie normale","De la manipulation de cours","D’une information périodique","D’un dividende"]$q_o_53$::jsonb, 1, $q_e_53$Fixer artificiellement un cours par ses ordres est une manipulation.$q_e_53$),
  ($q_n_54$expert$q_n_54$, $q_q_54$Un ami salarié d’une société cotée vous annonce un excellent résultat, pas encore publié. Que faire ?$q_q_54$, $q_o_54$["Acheter avant que l’annonce ne soit publiée","Ne pas opérer : l’information est privilégiée","La relayer à d’autres pour qu’ils en profitent","Vendre à découvert pour couvrir le risque"]$q_o_54$::jsonb, 1, $q_e_54$Utiliser ou transmettre une information privilégiée est interdit, pour lui comme pour vous.$q_e_54$),
  ($q_n_55$expert$q_n_55$, $q_q_55$Qui enquête et sanctionne les abus de marché dans l’UMOA ?$q_q_55$, $q_o_55$["La BRVM seule","L’AMF-UMOA","Chaque SGI","Personne"]$q_o_55$::jsonb, 1, $q_e_55$L’AMF-UMOA enquête et sanctionne ; des poursuites pénales relèvent des législations nationales.$q_e_55$),
  ($q_n_56$expert$q_n_56$, $q_q_56$Qu’est-ce qu’une « fenêtre négative » (black-out period) appliquée aux dirigeants d’une société cotée ?$q_q_56$, $q_o_56$["Une interdiction temporaire d’intervenir sur les titres avant publication","Une suspension automatique de l’action pendant trois mois consécutifs","Une exonération fiscale accordée aux fondateurs lors des dividendes","Une séance réservée aux ordres exécutés par la SGI chef de file"]$q_o_56$::jsonb, 0, $q_e_56$Avant la publication des comptes, les dirigeants doivent s’abstenir d’acheter ou de vendre afin d’éviter tout soupçon de délit d’initié.$q_e_56$),
  ($q_n_57$expert$q_n_57$, $q_q_57$Deux complices se vendent et s’achètent simultanément le même titre au même prix pour gonfler le volume affiché. De quel abus s’agit-il ?$q_q_57$, $q_o_57$["D’une offre publique d’achat obligatoire","D’une manipulation de marché par opérations fictives","D’un fractionnement régulier de la valeur nominale","D’une couverture réglementaire imposée par le DC/BR"]$q_o_57$::jsonb, 1, $q_e_57$Créer une apparence artificielle d’activité ou de liquidité trompe les autres investisseurs : c’est une manipulation de cours prohibée.$q_e_57$),
  ($q_n_58$expert$q_n_58$, $q_q_58$Transmettre à un proche un tuyau confidentiel avant la publication officielle d’une acquisition constitue :$q_q_58$, $q_o_58$["Une pratique courante tolérée hors séance boursière","Une communication illicite d’information privilégiée","Un service commercial normal entre actionnaires individuels","Une obligation liée à la transparence financière permanente"]$q_o_58$::jsonb, 1, $q_e_58$Communiquer une information privilégiée hors du cadre professionnel normal expose l’initié et le bénéficiaire à des sanctions.$q_e_58$),
  ($q_n_59$expert$q_n_59$, $q_q_59$Quel type de message relayé sur les réseaux sociaux peut être sanctionné au titre de la manipulation de marché ?$q_q_59$, $q_o_59$["La diffusion d’informations fausses ou trompeuses sur une société","La lecture publique du dernier bilan annuel officiel certifié","Le calcul d’un multiple PER à partir du Bulletin officiel de la cote","L’analyse comparative de deux exercices historiques déjà publiés"]$q_o_59$::jsonb, 0, $q_e_59$Propager sciemment des rumeurs fausses ou trompeuses susceptibles d’orienter artificiellement le cours relève de l’abus de marché.$q_e_59$),
  ($q_n_60$expert$q_n_60$, $q_q_60$Quelle distinction sépare le travail d’enquête de la décision de sanction à l’AMF-UMOA ?$q_q_60$, $q_o_60$["La Commission des sanctions statue indépendamment des enquêteurs","Les deux rôles reviennent uniquement au directeur général de la BRVM","Seules les SGI votent les amendes lors des assemblées générales","La BCEAO tranche les dossiers en remplaçant les juges civils"]$q_o_60$::jsonb, 0, $q_e_60$Pour garantir un procès équitable, les poursuites et l’instruction sont séparées de l’organe indépendant qui prononce les sanctions.$q_e_60$),
  ($q_n_61$expert$q_n_61$, $q_q_61$Depuis quand le marché des actions de la BRVM est-il organisé en compartiments Prestige, Principal et Croissance ?$q_q_61$, $q_o_61$["1998","2 janvier 2023","1er octobre 2022","2026"]$q_o_61$::jsonb, 1, $q_e_61$La réorganisation est entrée en vigueur le 2 janvier 2023.$q_e_61$),
  ($q_n_62$expert$q_n_62$, $q_q_62$Quel flottant minimum le compartiment Prestige exige-t-il ?$q_q_62$, $q_o_62$["5 % du capital","20 % du capital","50 % du capital","Aucun"]$q_o_62$::jsonb, 1, $q_e_62$Le communiqué de la BRVM fixe un flottant d’au moins 20 % du capital, assorti d’un nombre minimal de titres fixé par le règlement des compartiments.$q_e_62$),
  ($q_n_63$expert$q_n_63$, $q_q_63$Que regroupe l’indice BRVM 30 ?$q_q_63$, $q_o_63$["Les 30 plus grandes capitalisations","Les 30 valeurs les plus échangées sur un trimestre","Les 30 plus anciennes sociétés","30 obligations"]$q_o_63$::jsonb, 1, $q_e_63$Le BRVM 30 regroupe les trente valeurs les plus échangées sur un trimestre.$q_e_63$),
  ($q_n_64$expert$q_n_64$, $q_q_64$À qui s’adresse le compartiment Croissance ?$q_q_64$, $q_o_64$["Aux banques uniquement","Aux PME et aux entreprises à fort potentiel de croissance","Aux États","Aux OPCVM"]$q_o_64$::jsonb, 1, $q_e_64$Le compartiment Croissance est destiné aux PME et aux entreprises à fort potentiel de croissance.$q_e_64$),
  ($q_n_65$expert$q_n_65$, $q_q_65$Une société du compartiment Prestige est-elle un placement sans risque ?$q_q_65$, $q_o_65$["Oui, puisqu’elle est parmi les plus grandes","Non : le compartiment ne dit rien du cours","Oui, si elle verse un dividende régulier","Oui, pendant ses dix premières années"]$q_o_65$::jsonb, 1, $q_e_65$Le classement repose sur des critères de taille, de flottant et d’information, pas sur une garantie de performance.$q_e_65$),
  ($q_n_66$expert$q_n_66$, $q_q_66$Comment sont pondérées les actions au sein de l’indice BRVM Composite ?$q_q_66$, $q_o_66$["De manière strictement égale entre les sociétés cotées","Selon leur capitalisation boursière respective sur la cote","Uniquement selon le montant du dividende versé l’année précédente","À parts fixes selon le pays d’implantation du siège social"]$q_o_66$::jsonb, 1, $q_e_66$Un indice pondéré par la capitalisation donne un poids proportionnel à la taille boursière de chaque émetteur.$q_e_66$),
  ($q_n_67$expert$q_n_67$, $q_q_67$Quelle différence distingue le BRVM 30 du BRVM Principal en termes de nature ?$q_q_67$, $q_o_67$["Le BRVM 30 est un indice, alors que le Principal est un compartiment","Le BRVM 30 réunit les obligations souveraines et le Principal les actions","Le BRVM Principal rassemble uniquement des PME non encore rentables","Le BRVM 30 mesure l’inflation moyenne de la zone UEMOA"]$q_o_67$::jsonb, 0, $q_e_67$Les compartiments (Prestige, Principal, Croissance) classent les sociétés admises ; le BRVM 30 est un indice mesurant les 30 valeurs les plus actives.$q_e_67$),
  ($q_n_68$expert$q_n_68$, $q_q_68$Quel principe permet à une société initialement cotée sur le compartiment Principal ou Croissance de changer de catégorie ?$q_q_68$, $q_o_68$["Le respect durable des critères exigés lors de la revue annuelle","Une décision libre prise par le PDG sans examen de la BRVM","Une augmentation ponctuelle du cours sur une seule séance","Le versement d’un dividende exceptionnel supérieur à 20 %"]$q_o_68$::jsonb, 0, $q_e_68$La BRVM vérifie périodiquement les critères de flottant, capitalisation, liquidité et gouvernance avant tout reclassement.$q_e_68$),
  ($q_n_69$expert$q_n_69$, $q_q_69$À quoi servent les indices sectoriels publiés parallèlement au BRVM Composite ?$q_q_69$, $q_o_69$["À suivre la performance d’un secteur précis face au marché global","À garantir un rendement minimal aux détenteurs d’actions bancaires","À remplacer les rapports annuels certifiés des entreprises cotées","À fixer le tarif des frais de courtage pratiqués par les SGI"]$q_o_69$::jsonb, 0, $q_e_69$Les indices sectoriels (Finance, Télécoms, Services publics, Distribution…) isolent la dynamique propre à chaque branche d’activité.$q_e_69$),
  ($q_n_70$expert$q_n_70$, $q_q_70$Pourquoi un indice large peut-il monter alors que la majorité des titres de la cote stagne ?$q_q_70$, $q_o_70$["Parce que deux ou trois très grosses capitalisations tirent la moyenne","Parce que la BRVM retire automatiquement les valeurs en baisse","Parce que l’indice intègre les dépôts à terme des banques centrales","Parce que les dividendes sont comptés en double dans le calcul"]$q_o_70$::jsonb, 0, $q_e_70$Dans un indice pondéré par la capitalisation, les plus grandes valeurs représentent une part majeure de la variation totale.$q_e_70$),
  ($q_n_71$expert$q_n_71$, $q_q_71$Dans une offre publique de vente, à qui va l’argent des souscripteurs ?$q_q_71$, $q_o_71$["À la société","Aux actionnaires qui cèdent leurs titres","À la BRVM","À l’AMF-UMOA"]$q_o_71$::jsonb, 1, $q_e_71$Une OPV porte sur des actions existantes : le produit va aux vendeurs.$q_e_71$),
  ($q_n_72$expert$q_n_72$, $q_q_72$Une offre de 10 millions d’actions reçoit des demandes pour 14,2 millions. Quel est le taux de souscription ?$q_q_72$, $q_o_72$["70 %","100 %","142 %","242 %"]$q_o_72$::jsonb, 2, $q_e_72$14,2 ÷ 10 = 142 %.$q_e_72$),
  ($q_n_73$expert$q_n_73$, $q_q_73$Dans le même cas, si toutes les demandes sont réduites de façon égale, quelle part de sa demande chacun reçoit-il ?$q_q_73$, $q_o_73$["Environ 50 %","Environ 70 %","100 %","142 %"]$q_o_73$::jsonb, 1, $q_e_73$10 ÷ 14,2 ≈ 70 % de la demande servie.$q_e_73$),
  ($q_n_74$expert$q_n_74$, $q_q_74$Quelle contrainte durable accepte une société en entrant en bourse ?$q_q_74$, $q_o_74$["Ne plus jamais verser de dividende","Publier régulièrement ses comptes et les faits importants","Fermer son capital","Changer de pays"]$q_o_74$::jsonb, 1, $q_e_74$La cotation impose une information périodique et permanente, sous le contrôle de l’AMF-UMOA.$q_e_74$),
  ($q_n_75$expert$q_n_75$, $q_q_75$Une introduction très sursouscrite garantit-elle une hausse du cours ?$q_q_75$, $q_o_75$["Oui, au moins pendant la première année","Non : la demande ne fixe pas le cours futur","Oui, si la société cotée est une banque solide","Oui, dès la première séance de cotation"]$q_o_75$::jsonb, 1, $q_e_75$Une forte demande ne garantit rien. Le cours dépend ensuite des résultats et du prix payé.$q_e_75$),
  ($q_n_76$expert$q_n_76$, $q_q_76$Lors d’une introduction réalisée uniquement par augmentation de capital, à qui reviennent les fonds versés par les nouveaux actionnaires ?$q_q_76$, $q_o_76$["Aux anciens actionnaires fondateurs qui cèdent leurs parts","Directement à l’entreprise pour financer ses projets ou sa dette","Au budget annuel du Dépositaire central et des SGI intermédiaires","En réserve bloquée non utilisable sur un compte de l’AMF-UMOA"]$q_o_76$::jsonb, 1, $q_e_76$L’émission d’actions nouvelles injecte de l’argent frais dans la trésorerie et renforce les fonds propres de la société.$q_e_76$),
  ($q_n_77$expert$q_n_77$, $q_q_77$Une société compte 8 millions d’actions et en émet 2 millions de nouvelles en bourse. Un actionnaire historique qui ne souscrit pas passe de 10 % du capital à :$q_q_77$, $q_o_77$["12,5 %","10,0 %","8,0 %","5,0 %"]$q_o_77$::jsonb, 2, $q_e_77$Il détenait 800 000 actions sur 8 M (10 %) ; après émission, il garde 800 000 actions sur 10 M au total, soit 8,0 % (dilution).$q_e_77$),
  ($q_n_78$expert$q_n_78$, $q_q_78$Quel engagement durable pèse sur une entreprise dès le premier jour de sa cotation ?$q_q_78$, $q_o_78$["Publier régulièrement des comptes audités et faits importants","Garantir un dividende fixe en croissance chaque trimestre","Racheter ses propres titres si le cours baisse sous le prix d’offre","Verser une prime annuelle à la BRVM proportionnelle au cours"]$q_o_78$::jsonb, 0, $q_e_78$La transparence périodique et permanente envers l’ensemble du marché devient une obligation continue de la société cotée.$q_e_78$),
  ($q_n_79$expert$q_n_79$, $q_q_79$Que désigne habituellement une clause d’incessibilité (« lock-up ») signée par les fondateurs à l’occasion d’une IPO ?$q_q_79$, $q_o_79$["Un blocage temporaire empêchant les cédants de vendre le reste","Une garantie de prix plancher offerte par la BRVM pendant un an","L’obligation faite au public de conserver ses titres dix ans","L’interdiction de distribuer des dividendes pendant cinq exercices"]$q_o_79$::jsonb, 0, $q_e_79$Le lock-up rassure les nouveaux actionnaires en évitant qu’un actionnaire majoritaire n’inonde le marché juste après l’introduction.$q_e_79$),
  ($q_n_80$expert$q_n_80$, $q_q_80$Quel coût spécifique faut-il intégrer lorsqu’une société prépare une introduction en bourse ?$q_q_80$, $q_o_80$["Les honoraires des conseils, des auditeurs et de la SGI chef de file","Le remboursement anticipé de l’ensemble de ses emprunts bancaires","Le paiement préalable des dividendes futurs sur cinq années","Une amende administrative perçue par les concurrents cotés"]$q_o_80$::jsonb, 0, $q_e_80$L’audit, le montage juridique, le syndicat de placement et la communication financière représentent un coût initial significatif.$q_e_80$),
  ($q_n_81$expert$q_n_81$, $q_q_81$Une fois l’action admise sur le marché secondaire, comment évolue son cours par rapport au prix fixe de l’offre publique ?$q_q_81$, $q_o_81$["Il se fixe librement selon la confrontation des ordres quotidiens","Il reste bloqué au prix de souscription durant douze mois complets","Il progresse mécaniquement du taux d’intérêt directeur de la BCEAO","Il est recalculé une fois par an par l’AMF-UMOA après l’assemblée"]$q_o_81$::jsonb, 0, $q_e_81$Dès la première cotation, le prix résulte uniquement de l’offre et de la demande dans le carnet d’ordres de la BRVM.$q_e_81$),
  ($q_n_82$expert$q_n_82$, $q_q_82$Quelle étape doit précéder toute offre au public ?$q_q_82$, $q_o_82$["La première cotation","Le visa de l’AMF-UMOA sur la note d’information","Le versement d’un dividende","L’allocation des titres"]$q_o_82$::jsonb, 1, $q_e_82$Aucune offre au public ne peut être ouverte avant le visa de l’AMF-UMOA.$q_e_82$),
  ($q_n_83$expert$q_n_83$, $q_q_83$Que signifie le visa de l’AMF-UMOA ?$q_q_83$, $q_o_83$["Que l’investissement est recommandé","Que l’information est complète et compréhensible","Que le cours montera","Que la société est garantie par l’État"]$q_o_83$::jsonb, 1, $q_e_83$Le visa porte sur l’information, pas sur l’opportunité d’investir.$q_e_83$),
  ($q_n_84$expert$q_n_84$, $q_q_84$Qui conduit l’opération et organise le placement auprès du public ?$q_q_84$, $q_o_84$["La BCEAO","La SGI chef de file","Le Dépositaire central","Chaque investisseur"]$q_o_84$::jsonb, 1, $q_e_84$La SGI chef de file pilote l’opération et centralise les ordres.$q_e_84$),
  ($q_n_85$expert$q_n_85$, $q_q_85$Vous demandez 1 000 titres dans une offre sursouscrite à 200 %, avec une réduction proportionnelle. Combien en recevez-vous ?$q_q_85$, $q_o_85$["250","500","1 000","2 000"]$q_o_85$::jsonb, 1, $q_e_85$À 200 %, chaque ordre est servi à moitié : 500 titres.$q_e_85$),
  ($q_n_86$expert$q_n_86$, $q_q_86$Le cours peut-il passer sous le prix d’offre après la première cotation ?$q_q_86$, $q_o_86$["Non, jamais","Oui : le prix d’offre n’est pas un plancher","Seulement le premier jour","Seulement pour les PME"]$q_o_86$::jsonb, 1, $q_e_86$Après la cotation, le cours résulte de l’offre et de la demande.$q_e_86$),
  ($q_n_87$expert$q_n_87$, $q_q_87$Dans le montage d’une introduction en bourse, que signifie un syndicat de placement agissant en « prise ferme » ou « garantie de bonne fin » ?$q_q_87$, $q_o_87$["Le syndicat s’engage à souscrire les titres éventuellement invendus","Les acheteurs particuliers promettent de ne jamais revendre leurs parts","La BRVM garantit que le cours doublera dès la première séance","L’État s’engage à racheter l’entreprise en cas de baisse du bénéfice"]$q_o_87$::jsonb, 0, $q_e_87$Contrairement au placement pour compte (« best efforts »), l’engagement de garantie sécurise la levée pour l’émetteur.$q_e_87$),
  ($q_n_88$expert$q_n_88$, $q_q_88$Quelle section d’une note d’information visée mérite en priorité une lecture attentive pour identifier ce qui pourrait fragiliser l’opération ?$q_q_88$, $q_o_88$["La rubrique consacrée aux facteurs de risque et à l’usage des fonds","La page de couverture mentionnant le nom de l’imprimeur officiel","L’adresse postale des succursales bancaires recevant les bulletins","Le calendrier des jours fériés bancaires des dix prochains exercices"]$q_o_88$::jsonb, 0, $q_e_88$Les facteurs de risque, la méthode de valorisation et la destination précise des capitaux éclairent le profil réel de l’IPO.$q_e_88$),
  ($q_n_89$expert$q_n_89$, $q_q_89$Que vérifie concrètement le visa apposé par l’AMF-UMOA sur la note d’information ?$q_q_89$, $q_o_89$["Que l’information présentée est complète, cohérente et compréhensible","Que le prix d’introduction retenu est mathématiquement sous-évalué","Que la société versera à coup sûr un dividende dès l’année suivante","Que le titre sera automatiquement intégré au BRVM 30 dès le premier jour"]$q_o_89$::jsonb, 0, $q_e_89$Le visa porte sur la qualité et la sincérité de l’information divulguée ; il ne constitue jamais une appréciation d’opportunité financière.$q_e_89$),
  ($q_n_90$expert$q_n_90$, $q_q_90$Pourquoi la période de centralisation des ordres prend-elle plusieurs jours entre la clôture de l’offre et la première cotation ?$q_q_90$, $q_o_90$["Pour agréger toutes les demandes des SGI et appliquer les allocations","Pour laisser le temps aux dirigeants de modifier le prix de l’offre","Pour verser un premier acompte sur dividende avant même l’ouverture","Pour convertir l’ensemble des ordres en devises étrangères hors UEMOA"]$q_o_90$::jsonb, 0, $q_e_90$Le chef de file consolide les souscriptions du réseau, calcule la réduction éventuelle et transmet les titres attribués au DC/BR.$q_e_90$),
  ($q_n_91$expert$q_n_91$, $q_q_91$Lorsque votre ordre de souscription est réduit de moitié dans une offre sursouscrite, qu’advient-il de la somme versée en trop à votre SGI ?$q_q_91$, $q_o_91$["Le reliquat de trésorerie est restitué sur votre compte espèces","La différence est conservée par la BRVM à titre de commission fixe","Le montant est converti automatiquement en actions d’une autre banque","La somme reste bloquée pendant cinq ans sans produire aucun intérêt"]$q_o_91$::jsonb, 0, $q_e_91$Vous ne réglez finalement que les titres effectivement servis ; l’excédent bloqué lors de la souscription vous est débloqué.$q_e_91$)
) AS v(niveau, question, options, correct, explication)
WHERE NOT EXISTS (
  SELECT 1 FROM public.academy_exam_questions existing
  WHERE existing.active AND existing.niveau = v.niveau AND existing.question = v.question
);

COMMIT;
